window.TXB=window.TXB||{};TXB["alab/Act"]={"1:1":"رويت لك في كتابي الأول، يا ثاوفيلس، جميع أعمال يسوع وتعاليمه، منذ بدء رسالته","1:2":"حتى اليوم الذي ارتفع فيه إلى السماء، بعدما قدم وصاياه، بالروح القدس، إلى الرسل الذين اختارهم.","1:3":"وخلال فترة أربعين يوما بعد آلامه، ظهر لهم مرات عديدة، وأثبت لهم أنه حي ببراهين كثيرة قاطعة، وحدثهم عن ملكوت الله.","1:4":"وبينما كان مجتمعا معهم، قال: «لا تتركوا أورشليم، بل ابقوا فيها منتظرين إتمام وعد الآب، الذي سبق أن حدثتكم عنه.","1:5":"فإن يوحنا عمد الناس بالماء؛ أما أنتم فستتعمدون بعد أيام قليلة بالروح القدس!»","1:6":"وقد سأله المجتمعون: «يا رب، أفي هذا الوقت تعيد الملك إلى إسرائيل؟»","1:7":"فأجابهم: «ليس لكم أن تعرفوا المواعيد والأوقات التي حددها الآب بسلطته.","1:8":"ولكن حينما يحل الروح القدس عليكم تنالون القوة، وتكونون لي شهودا في أورشليم واليهودية كلها، وفي السامرة، وإلى أقاصي الأرض».","1:9":"قال هذا وارتفع إلى السماء وهم ينظرونه. ثم حجبته سحابة عن أنظارهم.","1:10":"وبينما هم يحدقون إلى السماء وهو ينطلق إليها، إذا رجلان قد ظهرا لهم بثياب بيض،","1:11":"وقالا لهم: «أيها الجليليون، لماذا تقفون ناظرين إلى السماء؟ إن يسوع، هذا الذي ارتفع عنكم إلى السماء، سيعود منها مثلما رأيتموه منطلقا إليها!»","1:12":"ثم رجع الرسل إلى أورشليم من الجبل المعروف بجبل الزيتون، وهو بالقرب من أورشليم على مسافة يجوز قطعها يوم السبت.","1:13":"ولما وصلوا صعدوا إلى غرفة في الطبقة العليا كانوا يقيمون فيها، وهم: بطرس ويوحنا، ويعقوب وأندراوس، وفيلبس وتوما، وبرثلماوس ومتى، ويعقوب بن حلفى وسمعان الغيور، ويهوذا أخو يعقوب.","1:14":"وكانوا جميعا يداومون على الصلاة بقلب واحد، ومعهم بعض النساء، ومريم أم يسوع، وإخوته.","1:15":"وكان قد اجتمع ذات يوم نحو مئة وعشرين من الإخوة فوقف بطرس بينهم وخاطبهم قائلا:","1:16":"«أيها الإخوة، كان لابد من أن تتم النبوءة التي قالها الروح القدس بلسان النبي داود، عن يهوذا الذي انقلب دليلا للذين قبضوا على يسوع.","1:17":"وكان يهوذا يعتبر واحدا منا، وقد شاركنا في خدمتنا.","1:18":"ثم إنه اشترى حقلا بالمال الذي تقاضاه ثمنا للخيانة، وفيه وقع على وجهه، فانشق من وسطه واندلقت أمعاؤه كلها.","1:19":"وعلم أهل أورشليم جميعا بهذه الحادثة، فأطلقوا على حقله اسم “حقل دمخ” بلغتهم، أي حقل الدم.","1:20":"فتمت النبوءة الواردة في كتاب المزامير: لتصر داره خرابا، ولا يسكنها ساكن. وأيضا: ليستلم وظيفته آخر!","1:21":"فعلينا إذن أن نختار واحدا من الرجال الذين رافقونا طوال المدة التي قضاها الرب يسوع معنا،","1:22":"منذ أن عمده يوحنا إلى يوم ارتفاعه عنا إلى السماء، ليكون معنا شاهدا بقيامة يسوع».","1:23":"فرشح الحاضرون رجلين هما: يوسف الذي يدعى بارسابا ويلقب بيستس، ومتياس.","1:24":"ثم صلوا قائلين: «أيها الرب العارف قلوب الناس جميعا، بين لنا أي هذين الرجلين تختار","1:25":"ليشاركنا في الخدمة والرسالة بدلا من يهوذا الذي ذهب إلى المكان الذي يستحقه».","1:26":"ثم ألقوا القرعة، فوقعت على متياس، فضموه إلى الرسل الأحد عشر.","2:1":"ولما جاء اليوم الخمسون، كان الإخوة مجتمعين معا في مكان واحد،","2:2":"وفجأة حدث صوت من السماء كأنه دوي ريح عاصفة، فملأ البيت الذي كانوا جالسين فيه.","2:3":"ثم ظهرت لهم ألسنة كأنها من نار، وقد توزعت وحلت على كل واحد منهم،","2:4":"فامتلأوا جميعا من الروح القدس، وأخذوا يتكلمون بلغات أخرى، مثلما منحهم الروح أن ينطقوا.","2:5":"وكانت أورشليم في ذلك الوقت مزدحمة باليهود الأتقياء الذين جاءوا إليها من أمم العالم كلها.","2:6":"فلما دوى الصوت، توافدت إليهم الجموع، وقد أخذتهم الحيرة لأن كل واحد كان يسمعهم يتكلمون بلغته.","2:7":"واستولت الدهشة عليهم. فأخذوا يتساءلون: «أليس هؤلاء المتكلمون جميعا من أهل الجليل؟","2:8":"فكيف يسمع كل واحد منا لغة البلد الذي ولد فيه؟","2:9":"فبعضنا فرتيون، وماديون، وعيلاميون. وبعضنا من سكان ما بين النهرين واليهودية، وكبدوكية، وبنتس، وأسيا،","2:10":"وفريجية، وبمفيلية، ومصر، ونواحي ليبيا المواجهة للقيروان. وبيننا كثيرون من الرومانيين الزائرين،","2:11":"يهودا ومتهودين، وبعض الكريتيين والعرب. وها نحن نسمعهم يكلموننا بلغاتنا عن أعمال الله العظيمة».","2:12":"وأخذ الجميع يسألون بعضهم بعضا في دهشة وحيرة: «ما معنى هذا كله؟»","2:13":"أما بعضهم فقالوا ساخرين: «ما هم إلا سكارى!»","2:14":"فوقف بطرس مع الرسل الأحد عشر، وخاطب الحاضرين بصوت عال، وقال: «أيها اليهود، ويا جميع المقيمين في أورشليم! أصغوا إلى كلامي لتعلموا حقيقة الأمر!","2:15":"ليس هؤلاء سكارى كما تتوهمون، فالناس لا يسكرون في الساعة التاسعة صباحا.","2:16":"ولكن هذا ما قيل بلسان النبي يوئيل:","2:17":"يقول الله: في الأيام الأخيرة سأسكب روحي على جميع البشر، فيتنبأ بنوكم وبناتكم، ويرى شبابكم رؤى، ويحلم شيوخكم أحلاما.","2:18":"في تلك الأيام أفيض من روحي على عبيدي كلهم، رجالا ونساء، فيتنبأون.","2:19":"سأجري عجائب فوق في السماء وعلامات تحت على الأرض، حيث يكون دم ونار ودخان كثيف!","2:20":"وقبل أن يأتي يوم الرب، ذلك اليوم العظيم الشهير، ستظلم الشمس، ويتحول القمر إلى لون الدم.","2:21":"ولكن كل من يدعو باسم الرب يخلص!","2:22":"فيا بني إسرائيل، اسمعوا هذا الكلام: إن يسوع الناصري رجل أيده الله بمعجزات وعجائب وعلامات أجراها على يده بينكم، كما تعلمون.","2:23":"ومع ذلك فقد سمح الله، وفقا لمشيئته المحتومة وعلمه السابق، أن تقبضوا عليه وتصلبوه وتقتلوه بأيدي الأثمة.","2:24":"ولكن الله أقامه من بين الأموات ناقضا أوجاع الموت، فما كان يمكن للموت أن يبقيه في قبضته!","2:25":"فإن داود يقول فيه: كنت أرى الرب أمامي دائما فإنه عن يميني لئلا أتزعزع.","2:26":"لذلك فرح قلبي وتهلل لساني. حتى إن جسدي سيرقد على رجاء.","2:27":"لأنك لن تترك نفسي في هوة الأموات، ولن تدع وحيدك القدوس يرى فسادا،","2:28":"هديتني سبل الحياة، وستملأني سرورا برؤية وجهك!","2:29":"أيها الإخوة، دعوني أقول لكم صراحة إن أبانا داود مات ودفن، وقبره مازال عندنا حتى اليوم.","2:30":"لأن داود كان نبيا، وعارفا أن الله أقسم له يمينا بأن يجيء المسيح من نسله ويجلس على عرشه،","2:31":"فقد تكلم عن قيامة المسيح كما رآها مسبقا، فقال إن نفسه لم تترك في هوة الأموات، ولم ينل من جسده الفساد.","2:32":"فيسوع هذا أقامه الله من الموت، ونحن جميعا شهود لذلك.","2:33":"وإذ رفع إلى يمين الله، وأخذ من الآب الروح القدس الموعود به، أفاضه علينا. وما ترونه الآن وتسمعونه هو نتيجة لذلك.","2:34":"فإن داود لم يرتفع بجسده إلى السماء. ثم إنه هو نفسه يقول: قال الرب لربي: اجلس عن يميني","2:35":"حتى أجعل أعداءك موطئا لقدميك.","2:36":"فليعلم يقينا بنو إسرائيل جميعا، أن الله قد جعل يسوع، هذا الذي صلبتموه أنتم، ربا ومسيحا!»","2:37":"فلما سمع الحاضرون هذا الكلام، وخزتهم قلوبهم، فسألوا بطرس وباقي الرسل: «ماذا نعمل أيها الإخوة؟»","2:38":"أجابهم بطرس: «توبوا، وليتعمد كل واحد منكم باسم يسوع المسيح، فيغفر الله خطاياكم وتنالوا هبة الروح القدس،","2:39":"لأن الوعد هو لكم ولأولادكم وللبعيدين جميعا، يناله كل من يدعوه الرب إلهنا!»","2:40":"ثم شهد بطرس للحاضرين ووعظهم بكلام كثير آخر، قائلا: «اخلصوا من هذا الجيل المنحرف!»","2:41":"فالذين قبلوا كلامه منهم تعمدوا. وانضم في ذلك اليوم نحو ثلاثة آلاف نفس.","2:42":"وكان الجميع يداومون على تلقي تعليم الرسل، وعلى حياة الشركة، وكسر الخبز، والصلوات.","2:43":"ولما أجريت عجائب وعلامات كثيرة على أيدي الرسل، استولت الرهبة على كل نفس.","2:44":"وكان المؤمنون كلهم متحدين معا، فكانوا يتشاركون في كل ما يملكون،","2:45":"ويبيعون أملاكهم ومقتنياتهم ويتقاسمون الثمن على قدر احتياج كل منهم،","2:46":"ويداومون على الحضور إلى الهيكل يوميا بقلب واحد، ويكسرون الخبز في البيوت، ويتناولون الطعام معا بابتهاج وبساطة قلب،","2:47":"مسبحين الله، وكانوا يلاقون استحسانا لدى الشعب كله. وكان الرب، كل يوم، يضم إلى الكنيسة الذين يخلصون.","3:1":"وذات يوم ذهب بطرس ويوحنا إلى الهيكل لصلاة الساعة الثالثة بعد الظهر.","3:2":"وعند باب الهيكل الذي يسمى الباب الجميل، كان يجلس رجل كسيح منذ ولادته، يحملونه كل يوم ويضعونه هناك ليطلب صدقة من الذين يدخلون الهيكل.","3:3":"فلما رأى بطرس ويوحنا داخلين، طلب منهما صدقة،","3:4":"فنظرا إليه مليا، وقال له بطرس: «انظر إلينا!»","3:5":"فتعلقت عيناه بهما، منتظرا أن يتصدقا عليه بشيء.","3:6":"فقال بطرس: «لا فضة عندي ولا ذهب، ولكني أعطيك ما عندي: باسم يسوع المسيح الناصري قم وامش!»","3:7":"وأمسكه بيده اليمنى وأقامه، فدبت القوة حالا في رجليه وكعبيه،","3:8":"فوقف قافزا وبدأ يمشي، ودخل معهما إلى الهيكل وهو يمشي ويقفز فرحا ويسبح الله.","3:9":"ورآه جميع الحاضرين ماشيا يسبح الله،","3:10":"وعرفوا أنه المستعطي الكسيح الذي تعود أن يقعد أمام الباب الجميل، فأخذتهم الدهشة والحيرة مما حدث له!","3:11":"وبينما كان في قاعة الهيكل المعروفة بقاعة سليمان ملازما بطرس ويوحنا، أسرع كثيرون من الشعب واجتمعوا حولهم مدهوشين،","3:12":"فقال لهم بطرس إذ رأى ذلك: «يا بني إسرائيل، لماذا تتعجبون مما حدث، ولماذا تحدقون إلينا كأننا بقدرتنا أو بتقوانا جعلنا هذا الرجل يمشي؟","3:13":"إن إله إبراهيم وإسحاق ويعقوب، إله آبائنا، قد مجد فتاه يسوع، الذي أسلمتموه أنتم للموت وأنكرتموه أمام بيلاطس، في حين كان يريد أن يطلقه.","3:14":"أنتم أنكرتم القدوس البار وطلبتم العفو عن رجل قاتل،","3:15":"وقتلتم واهب الحياة. ولكن الله أقامه من بين الأموات ونحن شهود لذلك.","3:16":"وبفضل الإيمان باسمه، أعاد اسمه القوة إلى هذا الرجل الذي ترونه وتعرفونه. فالإيمان بيسوع هو الذي أعطاه هذه الصحة الكاملة بمشهد منكم جميعا.","3:17":"إني أعلم أيها الإخوة أنكم ورؤساءكم عاملتم المسيح بجهل،","3:18":"ولكن الله أتم بذلك ما كان قد أوحى به إلى جميع أنبيائه من أن المسيح سيلاقي الآلام.","3:19":"فتوبوا وارجعوا ليمحو الله خطاياكم،","3:20":"وتأتيكم أيام الفرج من قبل الرب، إذ يرسل إليكم يسوع المسيح ثانية، الذي سبق أن عينه لكم،","3:21":"إذ لابد أن يبقى المسيح في السماء حتى يأتي الزمن الذي يتم فيه الإصلاح الشامل لكل شيء كما أوحى الله إلى أنبيائه الأتقياء منذ القدم.","3:22":"وقد قال موسى: سيبعث الله فيكم من بين إخوتكم نبيا مثلي فاسمعوا له في كل ما يكلمكم به.","3:23":"أما من لا يسمع له فسيباد من وسط الشعب.","3:24":"وكذلك تنبأ بهذه الأزمنة جميع الأنبياء، من صموئيل إلى الذين جاءوا بعده.","3:25":"وأنتم أحفاد هؤلاء الأنبياء، وأبناء العهد الذي أبرمه الله لآبائنا عندما قال لإبراهيم: بنسلك تنال البركة شعوب الأرض كلها.","3:26":"فمن أجلكم أولا أقام الله فتاه يسوع وأرسله ليبارككم برد كل واحد منكم عن شروره».","4:1":"وبينما كان بطرس ويوحنا يخاطبان الحاضرين، أقبل إليهما الكهنة، وقائد حرس الهيكل والصدوقيون،","4:2":"متضايقين لأنهما كانا يعلمان الناس ويعلنان أن قيامة الأموات حقيقة تؤكدها قيامة يسوع،","4:3":"فقبضوا عليهما وألقوهما في السجن إلى اليوم التالي، لأن المساء كان قد حل.","4:4":"وكان كثيرون ممن سمعوا الكلمة قد آمنوا فصار عدد المؤمنين من الرجال نحو خمسة آلاف.","4:5":"وفي صباح اليوم التالي اجتمع في أورشليم رؤساء اليهود والشيوخ والكتبة،","4:6":"ومعهم حنان رئيس الكهنة، وقيافا، ويوحنا، والإسكندر، وجميع المنتمين إلى عشيرة رؤساء الكهنة.","4:7":"واستدعوا بطرس ويوحنا وسألوهما: «بأية قوة، وباسم من فعلتما هذا؟»","4:8":"فامتلأ بطرس من الروح القدس وأجابهم: «يا رؤساء الشعب ويا شيوخه،","4:9":"إن كنتم تستجوبوننا اليوم بسبب الإحسان إلى إنسان مريض لتعرفوا كيف شفي،","4:10":"فاعلموا جميعا، وليعرف شعب إسرائيل كله، أنه باسم يسوع المسيح الناصري الذي صلبتموه أنتم، والذي أقامه الله من بين الأموات، باسمه يقف هذا الكسيح أمامكم في تمام الصحة!","4:11":"يسوع هذا هو الحجر الذي رفضتموه أيها البناة، وهو نفسه صار حجر الزاوية الأساسي،","4:12":"وليس بأحد غيره الخلاص، إذ ليس تحت السماء اسم آخر قدمه الله للبشر به يجب أن نخلص!»","4:13":"فتعجب المجتمعون من جرأة بطرس ويوحنا، لما عرفوا أنهما غير متعلمين وأنهما من عامة الشعب، فأدركوا أنهما كانا مع يسوع.","4:14":"ولكن إذ رأوا الكسيح الذي شفي واقفا معهما، لم يجدوا شيئا يعارضون به!","4:15":"فأمروهما بالخروج من المجلس، ليتشاوروا فيما بينهم.","4:16":"وقالوا: «ماذا نعمل بهذين الرجلين؟ فمن الواضح أمام أهل أورشليم جميعا أن معجزة عظيمة قد جرت على أيديهما، ولا نستطيع أن ننكر!","4:17":"ولكن لئلا يزداد هذا الأمر انتشارا بين الشعب، فلنهددهما ألا يذكرا هذا الاسم لأحد من الناس بعد الآن».","4:18":"ثم أحضروهما وأمروهما ألا ينطقا باسم يسوع ولا يعلما الناس به.","4:19":"ولكن بطرس ويوحنا قالا: «احكموا أنتم: أمن الحق أمام الله أن نطيع أمركم لا أمر الله؟","4:20":"لا نستطيع أن نكف عن التحدث بما رأينا وسمعنا».","4:21":"فشدد المجلس إنذاره لهما، دون أن يجد طريقة لمعاقبتهما، وأمر بإطلاقهما خوفا من ثورة الشعب، فقد كان الجميع يمجدون الله على تلك المعجزة،","4:22":"لأن الرجل الذي جرت فيه علامة الشفاء هذه قد جاوز الأربعين عاما!","4:23":"وما إن أطلق بطرس ويوحنا حتى رجعا إلى رفاقهما، وأخبراهم بكل ما قاله لهما رؤساء الكهنة والشيوخ،","4:24":"فتوجهوا بقلب واحد إلى الله بالدعاء، قائلين: «يا رب، يا خالق السماء والأرض والبحر وكل ما فيها،","4:25":"يا من قلت بالروح القدس على لسان عبدك داود: لماذا ضجت الأمم؟ ولماذا تآمرت الشعوب باطلا؟","4:26":"اجتمع ملوك الأرض ورؤساؤها، وتحالفوا ليقاوموا الرب ومسيحه!","4:27":"وقد تحققت هذه الكلمات فعلا، إذ تحالف هيرودس، وبيلاطس البنطي، والوثنيون وأسباط إسرائيل، لمقاومة فتاك القدوس يسوع، الذي جعلته مسيحا،","4:28":"وعملوا به كل ما سبق أن رسمت يدك وقضت مشيئتك أن يكون.","4:29":"والآن انظر، يا رب، إلى تهديدهم، وهبنا نحن عبيدك أن نعلن كلامك بكل جرأة،","4:30":"ومد يدك للشفاء، كي تجرى معجزات وعجائب باسم فتاك القدوس يسوع».","4:31":"وفيما هم يصلون ارتج المكان الذي كانوا مجتمعين فيه، وامتلأوا جميعا بالروح القدس، فأخذوا يعلنون كلمة الله بكل جرأة!","4:32":"وكانت جماعة المؤمنين قلبا واحدا ونفسا واحدة، ولم يكن أحد يقول إن شيئا مما عنده هو له وحده، بل كان كل شيء عندهم مشتركا.","4:33":"وكان الرسل يؤدون الشهادة بقيامة الرب يسوع وقوة عظيمة تصحبها، ونعمة عظيمة تحل على جميعهم.","4:34":"فلم يكن فيهم محتاج، لأن جميع من كان لهم حقول أو بيوت كانوا يبيعونها ويأتون بثمنها،","4:35":"فيضعونه عند أقدام الرسل، وهم يوزعونه على كل محتاج بقدر حاجته.","4:36":"ومن هؤلاء يوسف، الذي دعاه الرسل برنابا أي ابن التشجيع، وهو من سبط لاوي، ويحمل الجنسية القبرصية.","4:37":"فإنه كان يملك حقلا، فباعه وجاء بثمنه ووضعه عند أقدام الرسل!","5:1":"ولكن رجلا اسمه حنانيا، اتفق مع زوجته سفيرة فباع حقلا كان يملكه،","5:2":"واحتفظ لنفسه بجزء من الثمن بعلم من زوجته، وجاء بما تبقى ووضعه عند أقدام الرسل.","5:3":"فقال له بطرس: «يا حنانيا، لماذا سمحت للشيطان أن يملأ قلبك، فكذبت على الروح القدس، واحتفظت لنفسك بجزء من ثمن الحقل؟","5:4":"أما كان بقي لك لو لم تبعه؟ وبعد بيعه أما كان لك حق الاحتفاظ بثمنه؟ لماذا قصدت في قلبك أن تغش؟ إنك لم تكذب على الناس، بل على الله!»","5:5":"فما إن سمع حنانيا هذا الكلام حتى سقط أرضا ومات! فاستولت الرهبة الشديدة على جميع الذين عرفوا ذلك.","5:6":"وقام بعض الشبان وكفنوا حنانيا، وحملوه إلى حيث دفنوه.","5:7":"وبعد نحو ثلاث ساعات حضرت زوجة حنانيا وهي لا تدري بما حدث،","5:8":"فسألها بطرس: «قولي لي: أبهذا المبلغ بعتما الحقل؟» فأجابت: «نعم، بهذا المبلغ».","5:9":"فقال لها بطرس: «لماذا اتفقت مع زوجك على امتحان روح الرب؟ ها قد وصل الشبان الذين دفنوا زوجك إلى الباب، وسيحملونك أيضا!»","5:10":"فوقعت حالا عند قدمي بطرس وماتت! ولما دخل الشبان وجدوها ميتة، فحملوا جثتها ودفنوها إلى جوار زوجها.","5:11":"فاستولت الرهبة الشديدة على الكنيسة كلها، وعلى كل من سمعوا ذلك الخبر.","5:12":"وجرت على أيدي الرسل معجزات وعجائب كثيرة بين الشعب. وكانوا كلهم يجتمعون بقلب واحد في قاعة سليمان بالهيكل.","5:13":"ولم يجرؤ أحد من خارج على الانضمام إليهم، بل كان الشعب يشيد بهم.","5:14":"وأخذ عدد المؤمنين بالرب يزداد بانضمام جماعات من الرجال والنساء.","5:15":"وكان الناس يحملون المرضى على فرشهم وأسرتهم إلى الشوارع، لعل ظل بطرس عند مروره يقع على أحد منهم فينال الشفاء.","5:16":"بل كانت الجموع من المدن والقرى المجاورة يأتون إلى أورشليم حاملين المرضى والمعذبين بالأرواح النجسة، فكانوا جميعا يبرأون.","5:17":"إلا أن رئيس الكهنة وجماعته المنتمين إلى مذهب الصدوقيين ملأتهم الغيرة من الرسل،","5:18":"فقبضوا عليهم وألقوهم في السجن العام.","5:19":"ولكن ملاكا من الرب فتح أبواب السجن في الليل وأطلقهم، وقال لهم:","5:20":"«اذهبوا إلى الهيكل، وقفوا معلنين للناس بشارة الحياة الجديدة كاملة!»","5:21":"فأطاعوا وذهبوا إلى الهيكل باكرا عند الفجر وبدأوا يعلمون. بينما عقد المجلس اجتماعا، بدعوة من رئيس الكهنة وجماعته، حضره شيوخ إسرائيل جميعا، وأمروا بإحضار الرسل من السجن،","5:22":"ولكن الحرس لم يجدوهم! فرجعوا يخبرون","5:23":"قائلين: «وجدنا أبواب السجن مغلقة بإحكام، والحراس واقفين أمامها، ولكن لما فتحناها لم نجد في الداخل أحدا!»","5:24":"فسيطر الذهول على قائد حرس الهيكل وعلى رؤساء الكهنة عندما سمعوا هذا الكلام، وتساءلوا: «إلام سينتهي هذا الأمر؟»","5:25":"ثم جاء رجل إلى المجلس يقول: «إن الرجال الذين ألقيتم في السجن هم الآن واقفون في الهيكل يعلمون الناس».","5:26":"فذهب قائد الحرس ورجاله، وجاءوا بالرسل بغير عنف، خوفا من أن يرجمهم الشعب.","5:27":"فلما مثلوا أمام المجلس استجوبهم رئيس الكهنة","5:28":"قائلا: «أمرناكم بشدة ألا تعلموا بهذا الاسم، ولكنكم قد ملأتم أورشليم بتعليمكم، وتريدون أن تحملونا مسؤولية سفك دمه!»","5:29":"فأجاب بطرس والرسل: «ينبغي أن يطاع الله لا الناس!","5:30":"إن إله آبائنا أقام يسوع، الذي قتلتموه أنتم معلقين إياه على الخشبة!","5:31":"ولكن الله رفعه إلى يمينه وجعله رئيسا ومخلصا ليمنح إسرائيل التوبة وغفران الخطايا؛","5:32":"ونحن نشهد على هذا، وكذلك يشهد الروح القدس الذي وهبه الله للذين يطيعونه».","5:33":"ولما سمع المجتمعون هذا الكلام اشتد غضبهم، وقرروا أن يقتلوا الرسل.","5:34":"ولكن أحد أعضاء المجلس، واسمه غمالائيل، وهو معلم للشريعة يتبع المذهب الفريسي، ويحترمه جميع الشعب، وقف وأمر أن يخرج الرسل بعض الوقت،","5:35":"ثم قال للمجتمعين: «يا بني إسرائيل، حذار أن تنفذوا ما تنوون أن تعملوه بهؤلاء الرجال.","5:36":"فمنذ مدة قصيرة قام ثوداس وادعى أنه شخص عظيم، فتبعه نحو أربع مئة رجل، ولكنه قتل وتفرق أتباعه، وانتهى أمره.","5:37":"ثم قام يهوذا الجليلي في زمن الإحصاء واستمال عددا كبيرا من الناس ليتبعوه، ولكنه هلك أيضا وتشتت أتباعه.","5:38":"فالآن أنصحكم أن تبتعدوا عن هؤلاء الرجال وتتركوهم وشأنهم. فإن كان هذا المبدأ أو هذا العمل من عند الناس، فلابد أن يتهدم،","5:39":"ولكن إن كان من عند الله فلن تتمكنوا أبدا من الوقوف في وجهه، وإلا جعلتم من أنفسكم أعداء لله أيضا».","5:40":"فعمل أعضاء المجلس بهذه النصيحة، واستدعوا الرسل، فجلدوهم وأمروهم ألا يعلموا باسم يسوع، ثم أطلقوهم.","5:41":"ولكن الرسل خرجوا من المجلس فرحين، لأنهم اعتبروا أهلا لأن يلقوا الإهانة من أجل اسم يسوع.","5:42":"وكانوا كل يوم، في الهيكل وفي البيوت، يعلمون ويبشرون بالمسيح يسوع بلا انقطاع.","6:1":"وإذ تكاثر التلاميذ في تلك الأيام، احتج اليهود اليونانيون على العبرانيين، لأن أراملهم لم يكن يحصلن على نصيب من الإعانات اليومية.","6:2":"فدعا الرسل الاثنا عشر جماعة التلاميذ وقالوا لهم: «لا يصح أن نترك نحن كلمة الله لنقوم بتوزيع الإعانات!","6:3":"فاختاروا، أيها الإخوة، سبعة رجال منكم، لهم شهادة حسنة، ممتلئين من الروح القدس والحكمة، فنعينهم ليقوموا بهذه المهمة.","6:4":"أما نحن، فنداوم على الصلاة وخدمة الكلمة».","6:5":"فاستحسنت الجماعة كلها هذا الرأي؛ ووقع الاختيار على استفانوس، وهو رجل مملوء من الإيمان والروح القدس، وفيلبس، وبروخورس، ونيكانور، وتيمون، وبرميناس، ونيقولاوس الأنطاكي المتهود.","6:6":"وقدموهم للرسل، فصلوا ووضعوا أيديهم عليهم.","6:7":"فزادت كلمة الله انتشارا، وتكاثر عدد التلاميذ في أورشليم، وأطاع الإيمان مجموعة كبيرة من الكهنة.","6:8":"وإذ كان استفانوس مملوءا بالإيمان والقوة، كان يعمل عجائب ومعجزات عظيمة بين الشعب.","6:9":"فعارضه بعض المنتمين إلى جماعة العبيد المحررين، يساندهم بعض اليهود من القيروان والإسكندرية، وغيرهم من مقاطعتي كيليكيا وأسيا، وأخذوا يجادلونه.","6:10":"ولكنهم لم يتمكنوا من مقاومة حكمته والروح الذي كان يتكلم به.","6:11":"فما كان منهم إلا أن دفعوا رشوة لبعض الأشخاص ليقولوا: «سمعنا استفانوس يتكلم كفرا على موسى وعلى الله!»","6:12":"فأثارت هذه التهمة الشعب والشيوخ والكتبة على استفانوس، فألقوا القبض عليه وجاءوا به إلى المجلس،","6:13":"وأقاموا عليه شهود زور ادعوا أنه: «لا يكف عن التعرض بكلامه للهيكل المقدس وللشريعة","6:14":"فقد سمعناه يقول إن يسوع الناصري سيهدم هذا الهيكل ويغير الطقوس التي تسلمناها من موسى».","6:15":"فلما نظر إليه جميع الحاضرين في المجلس رأوا وجهه كأنه وجه ملاك.","7:1":"وسأل رئيس الكهنة استفانوس: «هل هذه الاتهامات صحيحة؟»","7:2":"فأجاب: «أيها الإخوة والآباء، اسمعوا: ظهر إله المجد لأبينا إبراهيم وهو في بلاد ما بين النهرين، قبل أن يرحل ليسكن في حاران،","7:3":"وقال له: اترك أرضك وعشيرتك، وارحل إلى الأرض التي أرشدك إليها.","7:4":"فأطاع ورحل من بلاد الكلدانيين، وسكن في حاران، وبقي فيها إلى أن مات أبوه، فجاء الله به إلى هذا البلد الذي تسكنون فيه الآن،","7:5":"ولم يعطه هنا ملكا، ولا موطئ قدم. ومع أنه كان وقتئذ بلا ولد، فإن الله وعده بأن يعطي هذا البلد له ولنسله من بعده.","7:6":"فقد قال الله: إن أحفاده سيقاسون الغربة في بلاد ليست لهم، مدة أربع مئة سنة يلاقون خلالها العبودية وسوء المعاملة؛","7:7":"ولكني أنزل العقاب بالشعب الذي يستعبدهم. وبعد ذلك يخرجون ويجيئون ليعبدوني في هذا المكان.","7:8":"وطلب الله إلى إبراهيم أن يختن الذكور في عائلته علامة على العهد الذي أبرمه له. فختن إبراهيم إسحاق في اليوم الثامن من عمره. وختن إسحاق ابنه يعقوب، وختن يعقوب أولاده الاثني عشر، الذين هم الآباء الأولون.","7:9":"وحسد الآباء الأولون يوسف وباعوه، فأصبح عبدا في مصر. ولكن الله كان معه،","7:10":"وأنقذه من جميع المحن التي مر بها، ووهبه نعمة وحكمة عند فرعون ملك مصر، فولاه على مصر، وعلى شؤون بيته.","7:11":"وحدثت بعد ذلك مجاعة في مصر وكنعان، فقاسى آباؤنا من ضيق شديد، إذ لم يجدوا الطعام.","7:12":"ولما سمع يعقوب أن في مصر قمحا أرسل إليها آباءنا أول مرة.","7:13":"وعندما أرسلهم مرة ثانية عرفهم يوسف بنفسه، وتبين لفرعون أصل يوسف.","7:14":"واستدعى يوسف والده يعقوب، وإخوته وعائلاتهم، إلى مصر وكانوا خمسة وسبعين شخصا.","7:15":"فجاء يعقوب وآباؤنا إلى مصر، وأقاموا فيها إلى أن ماتوا،","7:16":"فنقلوا إلى شكيم حيث دفنوا في القبر الذي اشتراه إبراهيم من قبيلة حمور أبي شكيم ببعض الفضة.","7:17":"وفيما كان يقترب إتمام الوعد الذي قطعه الله لإبراهيم، كان الشعب في مصر يتكاثرون ويزدادون عددا.","7:18":"ثم قام على مصر ملك جديد لم يكن يعرف أمر يوسف.","7:19":"فغدر بشعبنا، وأساء معاملة آبائنا، حتى أجبرهم على التخلي عن أطفالهم ليموتوا.","7:20":"في تلك الفترة ولد موسى. وكان جميلا جدا، فرباه والداه في بيتهما ثلاثة أشهر،","7:21":"ولكنهما اضطرا أخيرا إلى التخلي عنه، فأنقذته ابنة فرعون وتبنته وربته.","7:22":"فتثقف موسى بعلوم مصر كلها، حتى صار مقتدرا في القول والعمل.","7:23":"ولما بلغ الأربعين من العمر خطر بقلبه أن يتفقد أحوال إخوته من بني إسرائيل،","7:24":"فرأى واحدا منهم يعتدي عليه مصري، فتدخل ليدافع عن المظلوم، وانتقم له فقتل المصري،","7:25":"على أمل أن يدرك إخوته أن الله سينقذهم على يده. غير أنهم لم يدركوا!","7:26":"وفي اليوم التالي وجد اثنين من إخوته يتعاركان، فحاول أن يصلح بينهما، قائلا: أنتما أخوان، فلماذا يعتدي أحدكما على الآخر؟","7:27":"فما كان من المعتدي على قريبه إلا أن دفعه بعيدا، وقال: من أقامك رئيسا وقاضيا علينا؟","7:28":"أتريد أن تقتلني كما قتلت المصري أمس؟","7:29":"وهنا هرب موسى من مصر إلى بلاد مديان، وعاش فيها غريبا. وهناك أنجب ولدين.","7:30":"وبعدما مضت أربعون سنة كان موسى في صحراء جبل سيناء، عندما ظهر له ملاك الرب في لهيب نار من عليقة تشتعل","7:31":"وأثار المنظر دهشة موسى، فاقترب ليستطلع الأمر، وإذا صوت الرب يناديه:","7:32":"أنا إله آبائك، إله إبراهيم وإسحاق ويعقوب! فارتعد موسى ولم يعد يجرؤ على أن ينظر.","7:33":"فقال له الرب: اخلع نعليك لأن المكان الذي تقف عليه هو أرض مقدسة!","7:34":"إني رأيت العذاب الذي يعانيه شعبي في مصر، وسمعت أنينهم، فنزلت لأنقذهم. والآن، هيا أرسلك إلى مصر!","7:35":"فموسى الذي رفضه شعبه قائلين: من أقامك رئيسا وقاضيا علينا؟ هو نفسه أرسله الله رئيسا ومحررا، يؤيده الملاك الذي ظهر له في العليقة!","7:36":"وقد أخرج الشعب من مصر وهو يجري عجائب ومعجزات فيها، وفي البحر الأحمر، وفي الصحراء مدة أربعين سنة.","7:37":"وموسى هذا هو الذي قال لبني إسرائيل: سيبعث الله لكم من بين إخوتكم نبيا مثلي.","7:38":"وهو الذي كان يقود جماعة الشعب في الصحراء، وقد قام بدور الوسيط بين الملاك الذي كلمه على جبل سيناء وآبائنا، فنقل إليكم وصايا الله الحية.","7:39":"ولكن آباءنا رفضوا أن يطيعوا موسى، ولم يعترفوا بقيادته، وحنت قلوبهم للرجوع إلى مصر،","7:40":"وقالوا لهرون: اصنع لنا آلهة تهدينا في سيرنا، فإننا لا نعلم ماذا جرى لموسى هذا الذي أخرجنا من بلاد مصر!","7:41":"فصنعوا صنما على صورة عجل في تلك الأيام وقدموا له ذبيحة، وابتهجوا بما صنعت أيديهم.","7:42":"فتحول الله عنهم وتركهم يعبدون كواكب السماء، كما جاء في كتاب الأنبياء: يا بني إسرائيل، هل قربتم لي ذبائح وتقدمات طوال أربعين سنة في الصحراء؟","7:43":"لا، بل حملتم خيمة الصنم مولوك، وكوكب الإله رمفان، التمثالين اللذين صنعتماهما لتسجدوا لهما! لذلك سأنفيكم إلى أبعد من بابل!","7:44":"وقد حمل آباؤنا معهم في الصحراء خيمة الشهادة. وكان الله قد أوصى موسى أن يقيمها على المثال الذي أطلعه عليه؛","7:45":"ثم دخلوا بها إلى هذه البلاد التي فتحوها بقيادة يشوع، بعدما طرد الله من أمامهم الشعوب الساكنة فيها. وظل آباؤنا يعبدون الله في الخيمة حتى أيام داود،","7:46":"الذي نال قبولا لدى الله، فسعى أن يجد بيتا لإله يعقوب.","7:47":"وتحققت هذه الرغبة على يد سليمان الذي بنى الهيكل.","7:48":"إلا أن العلي لا يسكن في هياكل تصنعها أيدي البشر، كما قال النبي:","7:49":"السماء عرشي، والأرض موطئ قدمي. فأي بيت تبنون لي؟ يقول الرب، وأي مكان تعدون لراحتي؟","7:50":"أليست يدي قد صنعت هذه الأشياء كلها؟»","7:51":"ثم قال استفانوس: «يا أصحاب الرقاب الصلبة والقلوب والآذان غير المختونة! إنكم دائما تقاومون الروح القدس. وكما فعل آباؤكم تفعلون!","7:52":"فأي نبي نجا من اضطهادهم وقد قتلوا الذين أنبأوا بمجيء البار الذي سلمتموه أنتم وقتلتموه!","7:53":"فأنتم أخذتم الشريعة من أيدي الملائكة، ولكنكم لم تطيعوها!»","7:54":"فلما سمع المجتمعون كلام استفانوس، ملأ الغيظ قلوبهم، وأخذوا يصرون بأسنانهم توعدا.","7:55":"فرفع استفانوس نظره إلى السماء، وهو ممتلئ من الروح القدس، فرأى مجد الله ويسوع واقفا عن يمين الله،","7:56":"فقال: «إني أرى السماء مفتوحة وابن الإنسان واقفا عن يمين الله!»","7:57":"فصاحوا صياحا شديدا، وسدوا آذانهم وهجموا عليه هجمة واحدة،","7:58":"ودفعوه إلى خارج المدينة، وأخذوا يرجمونه بالحجارة. وخلع الشهود ثيابهم عند قدمي شاب اسمه شاول لكي يحرسها.","7:59":"وبينما كانوا يرجمون استفانوس، كان يدعو: «أيها الرب يسوع، اقبل روحي!»","7:60":"ثم ركع وصرخ بصوت عال: «يا رب، لا تحسب عليهم هذه الخطيئة!» وإذ قال هذا رقد.","8:1":"وكان شاول موافقا على قتل استفانوس. وفي ذلك اليوم وقع اضطهاد شديد على الكنيسة التي في أورشليم. فتشتت الإخوة جميعا في نواحي اليهودية والسامرة، ولم يبق في أورشليم إلا الرسل.","8:2":"وأما استفانوس فقد دفنه بعض الرجال الأتقياء، وناحوا عليه كثيرا.","8:3":"أما شاول فكان يحاول إبادة الكنيسة، فيذهب من بيت إلى بيت ويجر الرجال والنساء ويلقيهم في السجن.","8:4":"والذين تشتتوا كانوا ينتقلون من مكان إلى مكان مبشرين بالكلمة.","8:5":"فذهب فيلبس إلى مدينة في منطقة السامرة، وأخذ يبشر أهلها بالمسيح.","8:6":"فأصغت الجموع إلى كلامه بقلب واحد، إذ سمعوا بالعلامات التي أجراها، أو رأوها بأنفسهم،","8:7":"فقد كان يأمر الأرواح النجسة، فتصرخ بصوت عال وتخرج من المسكونين بها، كما شفى كثيرين من المشلولين والعرج،","8:8":"فعمت الفرحة أنحاء المدينة.","8:9":"وكان قبل ذلك في تلك المدينة ساحر اسمه سيمون، يمارس السحر فيذهل أهل السامرة ويدعي أنه رجل عظيم.","8:10":"فأصغى إليه الجميع من الصغير إلى الكبير، قائلين: «هذا الرجل هو قدرة الله العظمى!»","8:11":"وإنما أصغوا إليه لأنهم كانوا قد انخدعوا مدة طويلة بحيله السحرية!","8:12":"فلما آمنوا بكلام فيلبس الذي بشرهم بملكوت الله وباسم يسوع، تعمدوا رجالا ونساء.","8:13":"وسيمون نفسه آمن وتعمد، فألصق نفسه بفيلبس، وإذ شاهد الآيات والمعجزات التي أجريت على يده، استولت عليه الدهشة.","8:14":"وسمع الرسل في أورشليم أن أهل السامرة قبلوا كلمة الله، فأرسلوا إليهم بطرس ويوحنا.","8:15":"فصليا لأجلهم لكي ينالوا الروح القدس،","8:16":"لأنه لم يكن قد حل بعد على أحد منهم، إلا أنهم كانوا قد تعمدوا باسم الرب يسوع.","8:17":"ثم وضعا أيديهما عليهم، فنالوا الروح القدس.","8:18":"ولما رأى سيمون أن الروح القدس قد حل على المؤمنين لما وضع الرسولان أيديهما عليهم، عرض على بطرس ويوحنا بعض المال، وقال لهما:","8:19":"«أعطياني أنا أيضا هذه السلطة لكي ينال الروح القدس من أضع عليه يدي».","8:20":"فقال له بطرس: «لتبق لك فضتك لهلاكك! لأنك ظننت أنك تقدر أن تشتري هبة الله بالمال!","8:21":"لا قسمة لك في هذا الأمر ولا نصيب، لأن قلبك ليس مخلصا تجاه الله.","8:22":"فتب عن شرك هذا واطلب إلى الله، عسى أن يغفر لك نية قلبك،","8:23":"لأني أراك تتخبط في مرارة العلقم وقيود الخطيئة!»","8:24":"فقال سيمون: «صليا أنتما إلى الرب من أجلي حتى لا ينزل بي شيء مما تشيران إليه».","8:25":"وبعدما شهد بطرس ويوحنا بكلمة الرب وأعلناها هناك، رجعا إلى أورشليم وقد بشرا قرى كثيرة في منطقة السامرة.","8:26":"ثم إن ملاكا من عند الرب كلم فيلبس فقال له: «قم اذهب نحو الجنوب، ماشيا على الطريق البرية بين أورشليم وغزة».","8:27":"فقام وذهب. وإذا رجل حبشي، خصي، يعمل وزيرا للشؤون المالية عند كنداكة ملكة الحبشة، كان قد حج إلى أورشليم للسجود فيها،","8:28":"وهو راجع إلى الحبشة راكبا في عربته، يقرأ في كتاب النبي إشعياء.","8:29":"فقال الروح لفيلبس: «تقدم ورافق هذه العربة!»","8:30":"فأسرع فيلبس وسمع الخصي يقرأ نبوءة إشعياء، فسأله: «أتفهم ما تقرأ؟»","8:31":"فأجاب: «كيف يمكنني ذلك إن لم يشرح لي أحد؟» ودعا فيلبس أن يصعد إلى العربة ويجلس معه.","8:32":"وكان الخصي قد وصل في فصل الكتاب الذي يقرأه إلى القول: «مثل شاة سيق إلى الذبح، ومثل الحمل الصامت بين يدي من يجزه، هكذا لم يفتح فاه!","8:33":"في أثناء تواضعه عومل بغير عدل. من يخبر عن نسله؟ فإن حياته قد انتزعت من الأرض!»","8:34":"وسأل الخصي فيلبس: «قل لي: إلى من يشير النبي بهذا القول؟ إلى نفسه أو إلى شخص آخر؟»","8:35":"فتكلم وأخذ يبشره بيسوع انطلاقا من كتاب النبي هذا.","8:36":"وبينما كانت العربة تسير بهما، وصلا إلى مكان فيه ماء، فقال الخصي: «ها هو الماء، فماذا يمنع أن أتعمد؟»","8:37":"فأجابه فيلبس: «هذا جائز إن كنت تؤمن من كل قلبك». فقال الخصي: «إني أومن بأن يسوع المسيح هو ابن الله».","8:38":"وأمر أن تقف العربة، فنزلا إلى الماء معا، وعمد فيلبس الخصي.","8:39":"وما إن طلعا من الماء حتى خطف روح الرب فيلبس، فلم يعد الخصي يراه. فتابع سفره بفرح.","8:40":"أما فيلبس فقد شوهد في أشدود، ثم سار يبشر كل مدينة حتى وصل إلى قيصرية.","9:1":"أما شاول فكان يفور بالتهديد والقتل على تلاميذ الرب. فذهب إلى رئيس الكهنة،","9:2":"وطلب منه رسائل إلى مجامع اليهود في دمشق لتسهيل القبض على أتباع هذا الطريق من الرجال والنساء، حيثما يجدهم، ليسوقهم مقيدين إلى أورشليم.","9:3":"وفيما هو منطلق إلى دمشق، وقد اقترب منها، لمع حوله فجأة نور من السماء،","9:4":"فوقع إلى الأرض وسمع صوتا يقول له: «شاول! شاول! لماذا تضطهدني؟»","9:5":"فسأل: «من أنت يا سيد؟» فجاءه الجواب: «أنا يسوع الذي أنت تضطهده، صعب عليك أن ترفس المناخس».","9:6":"فقال وهو مرتعد ومتحير؛ «يا رب ماذا تريد أن أفعل؟» فقال له الرب: «قم، وادخل المدينة فيقال لك ما يجب أن تفعله».","9:7":"وأما مرافقو شاول فوقفوا مذهولين لا ينطقون، فقد سمعوا الصوت ولكنهم لم يروا أحدا.","9:8":"وعندما نهض شاول عن الأرض، فتح عينيه فوجد أنه لا يبصر، فاقتادوه بيده وأدخلوه إلى دمشق،","9:9":"حيث بقي ثلاثة أيام لا يبصر ولا يأكل ولا يشرب.","9:10":"وكان في دمشق تلميذ للرب اسمه حنانيا، ناداه الرب في رؤيا: «يا حنانيا!» فقال: «لبيك يا رب!»","9:11":"فقال له الرب: «اذهب إلى الشارع المعروف بالمستقيم واسأل في بيت يهوذا، عن رجل من طرسوس اسمه شاول. إنه يصلي هناك الآن.","9:12":"وقد رأى في رؤيا رجلا اسمه حنانيا يدخل إليه ويضع يده عليه، فيبصر».","9:13":"فقال حنانيا للرب: «ولكني، يا رب، قد سمعت من كثيرين بالفظائع التي ارتكبها هذا الرجل بقديسيك في أورشليم،","9:14":"وقد كلفه رؤساء الكهنة السلطة ليلقي القبض على كل من يدعو باسمك».","9:15":"فأمره الرب: «اذهب! فقد اخترت هذا الرجل ليكون إناء يحمل اسمي إلى الأمم والملوك وبني إسرائيل.","9:16":"وسأريه كم ينبغي أن يتألم من أجل اسمي!»","9:17":"فذهب حنانيا ودخل بيت يهوذا، ووضع يديه على شاول وقال: «أيها الأخ شاول، إن الرب يسوع، الذي ظهر لك في الطريق التي جئت فيها، أرسلني إليك لكي تبصر وتمتلئ من الروح القدس».","9:18":"وفي الحال تساقط من عيني شاول ما يشبه القشور، فأبصر، ثم قام وتعمد.","9:19":"وتناول طعاما فاستعاد قوته وبقي بضعة أيام مع التلاميذ في دمشق.","9:20":"وفي الحال بدأ يبشر في المجامع بأن يسوع هو ابن الله.","9:21":"وأثار كلامه دهشة السامعين، فتساءلوا: «أليس هذا هو الذي كان يبيد جميع الداعين بهذا الاسم في أورشليم؟ أما جاء إلى هنا ليلقي القبض عليهم ويسوقهم مقيدين إلى رؤساء الكهنة؟»","9:22":"وأما شاول فقد صار أكثر حماسة في وعظه، فكان يفحم اليهود الساكنين في دمشق ببراهينه التي كان يبين بها أن يسوع هو المسيح.","9:23":"وبعد عدة أيام، حاك اليهود في دمشق مؤامرة لقتل شاول،","9:24":"فعلم بها. وكانوا يراقبون أبواب المدينة نهارا وليلا ليقتلوه وهو يخرج منها.","9:25":"فأخذه بعض التلاميذ ليلا ووضعوه في سل، وأنزلوه بالحبال من على سور المدينة.","9:26":"ولما وصل شاول إلى أورشليم، حاول أن ينضم إلى التلاميذ هناك، فخافوا منه، إذ لم يصدقوا أنه صار تلميذا للرب.","9:27":"فتولى برنابا أمره وأحضره إلى الرسل، وحدثهم كيف ظهر الرب له في الطريق وكلمه، وكيف بشر بجرأة باسم يسوع في دمشق.","9:28":"فأخذ يذهب ويجيء معهم في أورشليم، مبشرا باسم الرب بجرأة.","9:29":"وكان يخاطب اليهود اليونانيين ويجادلهم، فحاولوا أن يقتلوه.","9:30":"فلما علم الإخوة بذلك أنزلوه إلى ميناء قيصرية. ومن هناك أرسلوه إلى طرسوس.","9:31":"في أثناء ذلك كانت الكنيسة في مناطق اليهودية والجليل والسامرة تتمتع بالسلام. وكانت تنمو وتسير في تقوى الرب، بمساندة الروح القدس.","9:32":"وبينما كان بطرس ينتقل من مكان إلى مكان، زار الساكنين في مدينة لدة،","9:33":"ووجد هناك مشلولا اسمه إينياس، مضت عليه ثماني سنوات وهو طريح الفراش.","9:34":"فقال له: «يا إينياس، شفاك يسوع المسيح. قم ورتب سريرك بنفسك!» فقام في الحال.","9:35":"ورآه سكان لدة وشارون جميعا، فرجعوا إلى الرب.","9:36":"وكان في مدينة يافا تلميذة اسمها طابيثا، ومعنى اسمها: غزالة، كان يشغلها دائما فعل الخير ومساعدة الفقراء.","9:37":"وحدث في ذلك الوقت أنها مرضت وماتت، فغسلوها ووضعوها في غرفة بالطبقة العليا.","9:38":"وسمع التلاميذ في يافا أن بطرس في لدة. وإذ كانت يافا قريبة من لدة، أرسلوا إليه رجلين يطلبان إليه قائلين: «تعال إلينا ولا تتأخر!»","9:39":"فقام وذهب. ولما وصل قادوه إلى الطبقة العليا، فتقدمت إليه جميع الأرامل باكيات، يعرضن بعض الأقمصة والثياب مما كانت غزالة تخيطه وهي معهن.","9:40":"فطلب بطرس إلى جميع الحاضرين أن يخرجوا من الغرفة، وركع وصلى، ثم التفت إلى الجثة وقال: «يا طابيثا، قومي!» ففتحت عينيها. ولما رأت بطرس جلست،","9:41":"فمد يده إليها وساعدها على النهوض، ثم دعا القديسين والأرامل، وردها إليهم حية.","9:42":"وانتشر خبر هذه المعجزة في يافا كلها، فآمن بالرب كثيرون.","9:43":"وبقي بطرس في يافا عدة أيام عند دباغ اسمه سمعان.","10:1":"وكان يسكن في قيصرية قائد مئة اسمه كرنيليوس، ينتمي إلى الكتيبة الإيطالية،","10:2":"وكان تقيا يخاف الله، هو وأهل بيته جميعا، يتصدق على الشعب كثيرا، ويصلي إلى الله دائما.","10:3":"وذات نهار نحو الساعة الثالثة بعد الظهر، رأى كرنيليوس في رؤيا واضحة ملاكا من عند الله يدخل إليه ويقول: «يا كرنيليوس!»","10:4":"فنظر إلى الملاك وقد استولى عليه الخوف، وسأل: «ماذا يا سيد؟» فأجابه: «صلواتك وصدقاتك صعدت أمام الله تذكارا.","10:5":"والآن أرسل بعض الرجال إلى يافا واستدع سمعان الملقب بطرس.","10:6":"إنه يقيم في بيت سمعان الدباغ عند البحر».","10:7":"فما إن ذهب الملاك الذي كان يكلم كرنيليوس، حتى دعا اثنين من خدمه، وجنديا تقيا من مرافقيه الدائمين،","10:8":"وروى لهم الخبر كله، وأرسلهم إلى يافا.","10:9":"وفي اليوم التالي، بينما كان الرجال الثلاثة يقتربون من مدينة يافا، صعد بطرس نحو الظهر إلى السطح ليصلي.","10:10":"وأحس جوعا شديدا، فاشتهى أن يأكل. وبينما الطعام يعد له، وقعت عليه غيبوبة،","10:11":"فرأى رؤيا: السماء مفتوحة، ووعاء يشبه قطعة كبيرة من القماش مربوطة بأطرافها الأربعة يتدلى إلى الأرض،","10:12":"وهو مليء بأنواع الحيوانات الدابة على الأرض والوحوش والزواحف وطيور السماء جميعا.","10:13":"وناداه صوت: «يا بطرس، قم اذبح وكل!»","10:14":"ولكن بطرس أجاب: «كلا يا رب، فأنا لم آكل قط شيئا محرما أو نجسا».","10:15":"فقال له الصوت أيضا: «ما طهره الله لا تحسبه أنت نجسا!»","10:16":"وتكرر هذا ثلاث مرات، ثم ارتفع الوعاء إلى السماء.","10:17":"تحير بطرس وأخذ يسائل نفسه عن معنى الرؤيا التي رآها. وإذا الرجال الذين أرسلهم كرنيليوس قد سألوا عن بيت سمعان الدباغ ووقفوا بالباب","10:18":"يستخبرون: «هل سمعان الملقب بطرس مقيم هنا؟»","10:19":"في هذه الأثناء كان بطرس يواصل التفكير في معنى الرؤيا، فقال له الروح: «بالباب ثلاثة رجال يطلبونك","10:20":"فانزل إليهم ورافقهم بلا تردد، فإني أنا أرسلتهم».","10:21":"فنزل إليهم وقال: «أنا الذي تطلبون. فما سبب حضوركم؟»","10:22":"فأجابوه: «قائد المئة كرنيليوس رجل صالح يتقي الله، ويشهد له بذلك شعب اليهود جميعا. وقد أوحى الله إليه بواسطة ملاك طاهر أن يستدعيك إلى بيته ليسمع ما عندك من كلام».","10:23":"فدعاهم بطرس ليمضوا الليلة ضيوفا بذلك البيت. وفي الصباح ذهب معهم، يرافقه بعض الإخوة من يافا،","10:24":"فوصلوا قيصرية في اليوم الثاني. وكان كرنيليوس ينتظر وصولهم، وقد دعا أقاربه وأصدقاءه المقربين.","10:25":"فما إن دخل بطرس حتى استقبله كرنيليوس ساجدا له،","10:26":"فأنهضه بطرس وقال: «قم! ما أنا إلا إنسان مثلك!»","10:27":"ودخل بطرس وهو يحادثه، فرأى جمعا كبيرا من الناس،","10:28":"فقال لهم: «أنتم تعلمون أنه محرم على اليهودي أن يتعامل مع الأجنبي أو يزوره في بيته. غير أن الله أراني ألا أقول عن إنسان ما إنه دنس أو نجس.","10:29":"فلذلك جئت من غير اعتراض، تلبية لدعوتكم. فما هو سبب دعوتكم لي؟»","10:30":"فأجاب كرنيليوس: «منذ أربعة أيام، في مثل هذه الساعة كنت أصلي في بيتي صلاة الساعة الثالثة بعد الظهر فظهر أمامي فجأة رجل يلبس ثوبا براقا","10:31":"وقال لي: يا كرنيليوس، سمع الله صلاتك وذكر صدقاتك.","10:32":"والآن أرسل رجالا إلى يافا، واستدع سمعان الملقب بطرس. إنه يقيم في بيت سمعان الدباغ عند البحر.","10:33":"فأرسلت حالا أدعوك، وقد أحسنت بمجيئك. ونحن الآن جميعا حاضرون أمام الله لنسمع كل ما أمرك به الرب».","10:34":"فبدأ بطرس كلامه قائلا: «تبين لي فعلا أن الله لا يفضل أحدا على أحد،","10:35":"بل يقبل من يتقيه ويعمل الصلاح مهما كانت جنسيته.","10:36":"وقد أرسل كلمته إلى بني إسرائيل، وبشرهم بالسلام بواسطة يسوع المسيح، رب الجميع.","10:37":"ولابد أنكم عرفتم بكل ما جرى في بلاد اليهود، وكان بدء الأمر في الجليل بعد المعمودية التي نادى بها يوحنا.","10:38":"فقد مسح الله يسوع الناصري بالروح القدس وبالقدرة، فكان ينتقل من مكان إلى مكان يعمل الخير، ويشفي جميع الذين تسلط عليهم إبليس، لأن الله كان معه.","10:39":"ونحن شهود على كل ما قام به في بلاد اليهود وفي أورشليم، وقد قتلوه حقا، معلقا على خشبة.","10:40":"ولكن الله أقامه من الموت في اليوم الثالث، وجعله يظهر،","10:41":"لا للشعب كله، بل للشهود الذين اختارهم الله من قبل، لنا نحن الذين أكلنا وشربنا معه بعد قيامته من بين الأموات.","10:42":"ثم أمرنا أن نبشر شعبنا به، ونشهد أنه هو الذي عينه الله ديانا للأحياء وللأموات.","10:43":"له يشهد جميع الأنبياء أن كل من يؤمن به ينل باسمه غفران الخطايا».","10:44":"وبينما كان بطرس يتكلم بهذا الكلام، حل الروح القدس على جميع الذين كانوا يسمعون.","10:45":"فدهش المؤمنون اليهود الذين جاءوا برفقة بطرس، لأن هبة الروح القدس فاضت أيضا على غير اليهود،","10:46":"إذ سمعوهم يتكلمون بلغات، ويسبحون الله. فقال بطرس:","10:47":"«أيستطيع أحد أن يمنع الماء فلا يتعمد أيضا هؤلاء الذين نالوا الروح القدس مثلنا؟»","10:48":"وأمر أن يتعمدوا باسم يسوع المسيح. ثم دعوه أن يقيم عندهم بضعة أيام.","11:1":"وسمع الرسل والإخوة في اليهودية أن غير اليهود أيضا قبلوا كلمة الله،","11:2":"فما إن عاد بطرس إلى أورشليم حتى جادله دعاة الختان، وعارضوه قائلين:","11:3":"«كيف دخلت بيت رجال غير مختونين، وأكلت معهم؟»","11:4":"فشرح لهم بطرس ما حدث على التوالي، وقال:","11:5":"«كنت أصلي في مدينة يافا، فوقعت علي غيبوبة، فرأيت في رؤيا وعاء يشبه قطعة كبيرة من القماش مربوطة بأطرافها الأربعة، وقد تدلى إلي من السماء.","11:6":"وعندما تأملته مليا وجدت فيه أنواع الحيوانات الدابة على الأرض والوحوش والزواحف وطيور السماء جميعا،","11:7":"وسمعت صوتا يقول لي: يا بطرس، قم اذبح وكل!","11:8":"فأجبت: كلا يا رب، فلم يدخل فمي قط شيء محرم أو نجس.","11:9":"فقال لي الصوت السماوي أيضا: ما طهره الله لا تحسبه أنت نجسا.","11:10":"وتكرر هذا ثلاث مرات، ثم سحب الوعاء بما فيه إلى السماء.","11:11":"وإذا ثلاثة رجال مرسلون إلي من قيصرية وصلوا إلى البيت الذي كنت مقيما فيه،","11:12":"فأمرني الروح أن أذهب معهم بلا تردد، فذهبت، ورافقني هؤلاء الإخوة الستة. وعند دخولنا بيت الرجل،","11:13":"أخبرنا كيف رأى الملاك في بيته واقفا وقائلا له: أرسل رجالا إلى يافا، واستدع سمعان الملقب بطرس،","11:14":"وهو يكلمك كلاما به تخلص أنت وأهل بيتك جميعا.","11:15":"ولما ابتدأت أتكلم، حل الروح القدس عليهم كما حل علينا في البداية","11:16":"فتذكرت ما قاله الرب لنا: إن يوحنا عمد بالماء، وأما أنتم فستتعمدون بالروح القدس.","11:17":"فإن كان الله قد ساواهم بنا فأعطاهم الهبة التي أعطانا إياها، إذ آمنا بالرب يسوع المسيح، فمن أكون أنا حتى أعيق الله؟»","11:18":"فلما سمع المعارضون هذا، سكتوا، ومجدوا الله قائلين: «إذن، قد أنعم الله أيضا على غير اليهود بالتوبة لنوال الحياة».","11:19":"أما المؤمنون الذين تشتتوا بسبب الاضطهاد الذي وقع عليهم بعد موت استفانوس، فمروا بفينيقية وقبرص وأنطاكية، وهم لا يبشرون بالكلمة إلا اليهود.","11:20":"غير أن بعضا منهم، وهم أصلا من قبرص والقيروان، وصلوا أنطاكية، وأخذوا يبشرون اليونانيين أيضا بالرب يسوع.","11:21":"فكانت يد الرب معهم، فآمن عدد كبير واهتدوا إلى الرب.","11:22":"ووصل خبر ذلك إلى الكنيسة في أورشليم، فأرسلوا برنابا إلى أنطاكية.","11:23":"فلما وصل ورأى النعمة التي منحها الله، امتلأ فرحا، وحث الجميع على الثبات في الرب بعزم القلب.","11:24":"فقد كان برنابا رجلا صالحا ممتلئا من الروح القدس والإيمان. وانضم إلى الرب جمع كبير.","11:25":"وتوجه برنابا إلى طرسوس يبحث عن شاول.","11:26":"ولما وجده جاء به إلى أنطاكية، فكانا يجتمعان مع الكنيسة هناك سنة كاملة، ويعلمان جمعا كبيرا. وفي أنطاكية أطلق على تلاميذ الرب أول مرة اسم المسيحيين.","11:27":"وفي تلك الأيام جاء إلى أنطاكية بعض الأنبياء من أورشليم،","11:28":"وبينهم نبي اسمه أغابوس، تنبأ بوحي من الروح أن مجاعة عظيمة ستحدث في البلاد كلها. وقد وقعت هذه المجاعة فعلا في عهد القيصر كلوديوس.","11:29":"لذلك قرر التلاميذ في أنطاكية أن يتبرع كل منهم بما يتيسر له، ويرسلوا إعانة إلى الإخوة المقيمين في اليهودية.","11:30":"ففعلوا ذلك، وأرسلوا الإعانة إلى الشيوخ بيد برنابا وشاول.","12:1":"في ذلك الوقت بدأ الملك هيرودس يضطهد بعض أفراد الكنيسة،","12:2":"فقتل يعقوب شقيق يوحنا بالسيف.","12:3":"ولما رأى أن هذا يرضي اليهود، قرر أن يقبض على بطرس أيضا، وكان ذلك في أيام عيد الفطير.","12:4":"فلما قبض عليه، أودعه السجن تحت حراسة أربع مجموعات من الحراس، تتكون كل مجموعة منها من أربعة جنود. وكان ينوي أن يسلمه إلى اليهود بعد عيد الفصح،","12:5":"فأبقاه في السجن. أما الكنيسة فكانت ترفع الصلاة الحارة إلى الله من أجله.","12:6":"وفي الليلة التي كان هيرودس قد نوى أن يسلم بطرس بعدها، كان بطرس نائما بين جنديين، مقيدا بسلسلتين، وأمام الباب جنود يحرسون السجن.","12:7":"وفجأة حضر ملاك من عند الرب، فامتلأت غرفة السجن نورا. وضرب الملاك بطرس على جنبه وأيقظه وقال: «قم سريعا!» فسقطت السلسلتان من يديه.","12:8":"فقال له الملاك: «شد حزامك، والبس حذاءك!» ففعل. ثم قال له: «البس رداءك واتبعني!»","12:9":"فخرج بطرس يتبع الملاك وهو يظن أنه يرى رؤيا، ولا يدري أن ما يجري على يد الملاك أمر حقيقي.","12:10":"واجتازا نقطة الحراسة الأولى ثم الثانية. ولما وصلا إلى باب السجن الحديدي الذي يؤدي إلى المدينة انفتح لهما من ذاته، فخرجا. وبعدما عبرا شارعا واحدا، فارقه الملاك حالا.","12:11":"عندئذ استعاد بطرس وعيه، فهتف: «الآن أيقنت أن الرب أرسل ملاكه فأنقذني من قبضة هيرودس، ومن توقعات شعب اليهود!»","12:12":"وإذ أدرك ذلك، اتجه إلى بيت مريم أم يوحنا الملقب مرقس، حيث كان عدد كبير من المؤمنين مجتمعين يصلون.","12:13":"ولما وصل قرع الباب الخارجي، فجاءت خادمة اسمها رودا لتتسمع.","12:14":"فلما عرفت صوت بطرس لم تفتح لشدة الفرح، بل أسرعت إلى داخل البيت تبشر الحاضرين بأن بطرس بالباب.","12:15":"فقالوا لها: «أنت تهذين!» ولكنها أكدت لهم الخبر، فقالوا: «لعله ملاك بطرس!»","12:16":"أما بطرس فواصل قرع الباب حتى فتحوا له. فلما رأوه استولت عليهم الدهشة!","12:17":"فأشار بيده أن يسكتوا، وحدثهم كيف أخرجه الرب من السجن، وقال: «أخبروا يعقوب والإخوة بهذا». ثم خرج وذهب إلى مكان آخر.","12:18":"ولما طلع الصباح حدثت بلبلة عظيمة بين الجنود، وأخذوا يتساءلون: «ما الذي جرى لبطرس؟»","12:19":"ولما أمر هيرودس باستدعائه ولم يجده، أجرى تحقيقا مع الحراس، وأمر بإعدامهم. ثم انتقل هيرودس من منطقة اليهودية إلى قيصرية، وأقام فيها.","12:20":"وكان ناقما على أهل صور وصيدا. فاتفقوا وأرسلوا وفدا منهم يستعطفون بلاستس حاجب الملك طالبين الأمان، لأن منطقتهم كانت تكسب رزقها من مملكة هيرودس.","12:21":"وفي اليوم المعين لمقابلة الوفد، ارتدى هيرودس ثوبه الملوكي، وجلس على عرشه يخاطبهم.","12:22":"فهتف الشعب قائلين: «هذا صوت إله لا صوت إنسان!»","12:23":"فضربه ملاك من عند الرب في الحال لأنه لم يعط المجد لله، فأكله الدود ومات!","12:24":"أما كلمة الرب فكانت تنمو وتزداد انتشارا.","12:25":"وكان برنابا وشاول قد أنجزا المهمة في أورشليم، فرجعا إلى أنطاكية ومعهما يوحنا الملقب مرقس.","13:1":"وكان في الكنيسة التي في أنطاكية بعض الأنبياء والمعلمين؛ ومنهم برنابا؛ وسمعان الذي يدعى الأسود؛ ولوكيوس من القيروان؛ ومناين الذي تربى في طفولته مع هيرودوس حاكم الربع؛ وشاول.","13:2":"وذات يوم، وهم صائمون يتعبدون للرب، قال لهم الروح القدس: «خصصوا لي برنابا وشاول لأجل العمل الذي دعوتهما إليه».","13:3":"فبعدما صاموا وصلوا ووضعوا عليهما أيديهم أطلقوهما.","13:4":"وإذ أرسل الروح القدس برنابا وشاول، توجها إلى ميناء سلوكية، وسافرا بحرا باتجاه قبرص.","13:5":"ولما وصلا الجزيرة نزلا في سلاميس، وأخذا يبشران بكلمة الله في مجامع اليهود، وكان يرافقهما يوحنا معاونا لهما.","13:6":"واجتازا الجزيرة كلها حتى وصلا بافوس. وهناك قابلا ساحرا يهوديا نبيا دجالا، اسمه باريشوع،","13:7":"وكان مقربا من سرجيوس بولس حاكم قبرص. وكان الحاكم ذكيا، فاستدعى برنابا وشاول، وطلب إليهما أن يكلماه بكلمة الله.","13:8":"فعارضهما الساحر عليم، وهذا معنى اسمه، ساعيا أن يحول الحاكم عن الإيمان.","13:9":"أما شاول، واسمه أيضا بولس، فامتلأ من الروح القدس، ونظر إلى الساحر وقال:","13:10":"«أيها الممتلئ غشا وخبثا! يا ابن إبليس! يا عدو كل بر! أما تكف عن تعويج طرق الرب المستقيمة؟","13:11":"الآن ستمتد يد الرب عليك، فتصير أعمى لا تبصر النور إلى حين». وفي الحال سقطت على عينيه غمامة مظلمة، فأخذ يدور طالبا من يقوده بيده!","13:12":"ولما رأى الحاكم ما جرى آمن مدهوشا من تعليم الرب.","13:13":"وأبحر بولس ورفيقاه من بافوس إلى برجة في بمفيلية. وهناك فارق يوحنا بولس وبرنابا ورجع إلى أورشليم.","13:14":"أما هما فسافرا من برجة إلى أنطاكية التابعة لمقاطعة بيسيدية. ودخلا المجمع اليهودي يوم السبت، وجلسا.","13:15":"وبعد قراءة من الشريعة وكتب الأنبياء، أرسل إليهما رؤساء المجمع يقولون: «أيها الأخوان، إن كان عندكما ما تعظان به المجتمعين، فتكلما».","13:16":"فوقف بولس، وأشار بيده، وقال: اسمعوا يا بني إسرائيل، ويا من تتقون الله:","13:17":"إن إله شعب إسرائيل هذا اختار آباءنا، ورفع من شأن شعبنا طوال غربتهم في مصر، ثم أخرجهم منها بقدرة ذراعه الفائقة.","13:18":"وعالهم في الصحراء نحو أربعين سنة،","13:19":"ثم أزال سبعة شعوب من بلاد كنعان، وأورثهم أرضها،","13:20":"نحو أربع مئة وخمسين سنة. بعد ذلك، أقام لهم قضاة كان آخرهم النبي صموئيل.","13:21":"فطلب إليه بنو إسرائيل أن يولي عليهم ملكا، فأقام الله عليهم شاول بن قيس، من سبط بنيامين، فملك عليهم أربعين سنة.","13:22":"ثم عزله الله، وعين بدلا منه داود الذي شهد له بقوله: إني وجدت داود بن يسى رجلا يوافق قلبي، سيعمل كل ما أشاء.","13:23":"وقد بعث الله إلى إسرائيل من نسل داود مخلصا هو يسوع، إتماما لوعده.","13:24":"وقد سبق يوحنا مجيء يسوع، فدعا شعب إسرائيل جميعا إلى معمودية التوبة.","13:25":"ولما أوشك يوحنا أن ينهي مهمته، قال: من تظنونني؟ لست أنا (المخلص)، بل إنه آت بعدي. ولست أستحق أن أحل رباط حذائه!","13:26":"أيها الإخوة، يا بني جنس إبراهيم، ويا كل من يتقي الله من الحاضرين هنا: إلينا أرسل الله كلمة هذا الخلاص!","13:27":"فإن أهل أورشليم ورؤساءهم عملوا على إتمام ما يقرأ عليكم كل يوم سبت من نبوءات، وهم لا يعلمون. إذ حكموا على يسوع بالموت،","13:28":"ومع أنهم لم يثبتوا عليه أي جرم يستحق الموت، طلبوا من بيلاطس أن يقتله.","13:29":"وبعدما نفذوا فيه كل ما كتب عنه، أنزلوه عن الصليب، ودفنوه في قبر.","13:30":"ولكن الله أقامه من بين الأموات،","13:31":"فظهر عدة أيام للذين رافقوه من منطقة الجليل إلى أورشليم. وهم الآن يشهدون بذلك أمام الشعب.","13:32":"وها نحن الآن نبشركم بأن ما وعد الله به آباءنا،","13:33":"قد أتمه لنا نحن أبناءهم، إذ أقام يسوع من الموت وفقا لما كتب في المزمور الثاني: أنت ابني؛ أنا اليوم ولدتك.","13:34":"وأما أن الله قد أقام يسوع من بين الأموات ولن يدع الفساد ينال منه فيما بعد، فقد ورد في قوله: سأمنحكم البركات المقدسة الصادقة التي وعدت بها داود.","13:35":"ويقول داود في مزمور آخر: لن تدع وحيدك القدوس يرى فسادا.","13:36":"وقد مات داود بعدما خدم شعبه في عصره وفقا لمشيئة الله، ودفن فلحق بآبائه، ونال منه الفساد.","13:37":"أما الذي أقامه الله فلم ينل منه الفساد قط.","13:38":"فاعلموا، أيها الإخوة، أنه بيسوع تبشرون بغفران الخطايا،","13:39":"وأنه به يتبرر كل من يؤمن من كل ما عجزت شريعة موسى أن تبرره منه.","13:40":"فاحذروا لئلا يحل بكم ما قيل في كتب الأنبياء:","13:41":"انظروا أيها المتهاونون، وتعجبوا واهلكوا! فإني أعمل في أيامكم عملا لو حدثكم به أحد لما صدقتم!»","13:42":"وفيما الحاضرون ينصرفون، طلبوا إلى بولس وبرنابا أن يعودا في السبت التالي ويحدثاهم بهذا الأمر.","13:43":"وتبعهما بعد الاجتماع كثيرون من اليهود والمتهودين العابدين، فأخذا يكلمانهم ويشجعانهم على الثبات في نعمة الله.","13:44":"وفي السبت التالي اجتمع أهل المدينة كلهم تقريبا ليسمعوا كلمة الله.","13:45":"فلما رأى اليهود الجموع ملأت الغيرة صدورهم، وأخذوا يعارضون كلام بولس مجدفين.","13:46":"فخاطبهم بولس وبرنابا بجرأة قائلين: «كان يجب أن نبلغكم أنتم أولا كلمة الله، ولكنكم رفضتموها فأظهرتم أنكم لا تستحقون الحياة الأبدية. وها نحن نتوجه إلى غير اليهود!","13:47":"فقد أوصانا الرب قائلا: قد جعلتك نورا للأمم، لتكون سبيل خلاص إلى أقصى الأرض!»","13:48":"فلما سمع غير اليهود ذلك، فرحوا جدا، ومجدوا كلمة الرب. وآمن جميع من أعدهم الله للحياة الأبدية.","13:49":"وهكذا انتشرت كلمة الرب في المنطقة كلها.","13:50":"ولكن اليهود حرضوا النساء النبيلات والمتعبدات ووجهاء المدينة، وأثاروا الاضطهاد على بولس وبرنابا، حتى طردوهما من بلدهم،","13:51":"فنفضا عليهم غبار أقدامهما وتوجها إلى مدينة إيقونية.","13:52":"أما التلاميذ، فقد امتلأوا من الفرح ومن الروح القدس.","14:1":"وفي إيقونية دخل بولس وبرنابا إلى المجمع اليهودي كعادتهما، وأخذا يتكلمان حتى آمن جمع كبير من اليهود واليونانيين.","14:2":"ولكن اليهود الذين لم يؤمنوا أثاروا غير اليهود على الإخوة، وأفسدوا عقولهم.","14:3":"إلا أن بولس وبرنابا بقيا هناك فترة طويلة يبشران بالرب بكل جرأة، وأيدهما الرب شاهدا لكلمة نعمته بما أجراه على أيديهما من آيات وعجائب.","14:4":"فانقسم أهل إيقونية فريقين: فمنهم من كان مع اليهود، ومنهم من كان مع الرسولين.","14:5":"ولما أوشك غير اليهود واليهود ورؤساؤهم أن يهينوا الرسولين ويرجموهما بالحجارة،","14:6":"علما بذلك فهربا إلى مدينتي لسترة ودربة الواقعتين في مقاطعة ليكأونية، وإلى المنطقة المحيطة بهما،","14:7":"وأخذا يبشران هناك.","14:8":"وكان يقيم في مدينة لسترة كسيح مقعد منذ ولادته لم يمش قط.","14:9":"فإذ كان يصغي إلى حديث بولس فرأى فيه إيمانا بأنه سيشفى،","14:10":"فناداه بأعلى صوته: «انهض واقفا على رجليك!» فقفز الرجل وبدأ يمشي.","14:11":"فلما رأى الحاضرون ما قام به بولس هتفوا باللغة الليكأونية: «اتخذ الآلهة صورة بشر ونزلوا بيننا!»","14:12":"ثم دعوا برنابا زفس وبولس هرمس، لأنه كان يدير الحديث.","14:13":"وكان عند مدخل المدينة معبد للإله زفس، فجاء كاهنه على رأس جمع من المدينة، وهم يحملون أكاليل الزهور ويجرون الثيران ليقدموها ذبيحة لبولس وبرنابا.","14:14":"فلما سمع الرسولان بذلك مزقا ثيابهما، وأسرعا إلى المجتمعين","14:15":"وهما يصرخان: «لماذا تفعلون هذا أيها الناس؟ ما نحن إلا بشر ضعفاء مثلكم، نبشركم بأن ترجعوا عن هذه الأشياء الباطلة إلى الله الحي صانع السماء والأرض والبحر، وكل ما فيها،","14:16":"وقد ترك الأمم في العصور الماضية يسلكون في طرقهم،","14:17":"مع أنه لم يتركهم دون شاهد يدلهم عليه. فهو مازال ينعم عليكم بالخير، ويرزقكم من السماء أمطارا ومواسم مثمرة، ويشبعكم طعاما ويملأ قلوبكم سرورا».","14:18":"بهذا الكلام تمكنا بعد جهد من إقناع الجموع بعدم تقديم الذبائح لهما.","14:19":"بعد ذلك جاء بعض اليهود من أنطاكية وإيقونية، واستمالوا الجموع، فرجموا بولس حتى ظنوا أنه مات، وجروه إلى خارج المدينة.","14:20":"ولما أحاط به التلاميذ، قام وعاد إلى المدينة. وفي اليوم التالي سافر مع برنابا إلى دربة،","14:21":"وبشرا أهلها، فصار كثيرون منهم تلاميذ للرب. ثم رجعا إلى لسترة، ومنها إلى إيقونية، وأخيرا إلى أنطاكية.","14:22":"وفي هذه الأماكن كلها كانا يشددان عزيمة التلاميذ، ويحثانهم على الثبات في الإيمان، مؤكدين لهم أن دخول ملكوت الله يقتضي أن نقاسي صعوبات كثيرة.","14:23":"وعينا للتلاميذ شيوخا في كل كنيسة. ثم صليا بأصوام وأسلما الجميع وديعة بين يدي الرب الذي آمنوا به.","14:24":"ثم سافرا من مقاطعة بيسيدية، ووصلا إلى بمفيلية.","14:25":"وبشرا بكلمة الله في برجة، ثم سافرا إلى أتالية.","14:26":"ومن هناك عادا بحرا إلى مدينة أنطاكية، حيث كان المؤمنون قد أسلموهما إلى نعمة الله ليقوما بالعمل الذي قد أنجزاه.","14:27":"ولما وصلا، استدعيا الكنيسة إلى الاجتماع، وأخبرا بكل ما فعل الله بواسطتهما، وبأنه فتح باب الإيمان لغير اليهود.","14:28":"وأقاما مع التلاميذ هناك مدة طويلة.","15:1":"وجاء قوم من منطقة اليهودية إلى أنطاكية، وأخذوا يعلمون الإخوة قائلين: «لا يمكنكم أن تخلصوا ما لم تختنوا حسب شريعة موسى»","15:2":"فجادلهم بولس وبرنابا جدالا عنيفا. وبعد المناقشة قرر مؤمنو أنطاكية أن يذهب بولس وبرنابا مع بعض المؤمنين ليقابلوا الرسل والشيوخ في أورشليم، ويبحثوا معهم في هذه القضية.","15:3":"وبعدما ودعتهم الكنيسة، سافروا إلى أورشليم مرورا بمدن فينيقية والسامرة، مخبرين الإخوة فيها بأن غير اليهود أيضا قد اهتدوا إلى المسيح، فأشاعوا بذلك فرحا كبيرا بين الإخوة جميعا.","15:4":"ولما وصلوا إلى أورشليم، رحبت بهم الكنيسة بمن فيها من رسل وشيوخ، فأخبروهم بكل ما فعل الله بواسطتهم.","15:5":"ولكن بعض الذين كانوا على مذهب الفريسيين، ثم آمنوا، وقفوا وقالوا: «يجب أن يختن المؤمنون من غير اليهود ويلزموا أن يعملوا بشريعة موسى».","15:6":"فعقد الرسل والشيوخ اجتماعا لدراسة هذه القضية.","15:7":"وبعد نقاش كثير، وقف بطرس وقال: «أيها الإخوة، أنتم تعلمون أنه منذ مدة طويلة شاء الله أن يسمع غير اليهود كلمة البشارة على لساني ويؤمنوا.","15:8":"وقد شهد الله العليم بما في القلوب على قبوله لهم إذ وهبهم الروح القدس كما وهبنا إياه.","15:9":"فهو لم يفرق بيننا وبينهم في شيء، إذ طهر بالإيمان قلوبهم.","15:10":"فلماذا تعارضون الله فتحملون تلاميذ الرب عبئا ثقيلا عجز الآباء وعجزنا نحن عن حمله؟","15:11":"فنحن نؤمن بأننا نخلص، كما يخلصون هم، بنعمة الرب يسوع».","15:12":"عندئذ توقف الجدال بين الحاضرين، وأخذوا يستمعون إلى برنابا وبولس وهما يخبرانهم بما أجراه الله بواسطتهما من علامات وعجائب بين غير اليهود.","15:13":"وبعد انتهائهما من الكلام، قال يعقوب:","15:14":"«استمعوا لي أيها الإخوة: أخبركم سمعان كيف تفقد الله منذ البداية غير اليهود ليتخذ من بينهم شعبا يحمل اسمه؛","15:15":"وتوافق هذا أقوال الأنبياء، كما جاء في الكتاب.","15:16":"سأعود من بعد هذا وأبني خيمة داود المنهدمة ثم أقيم أنقاضها وأبنيها من جديد،","15:17":"لكي يسعى إلى الرب باقي الناس وجميع الشعوب التي تحمل اسمي، يقول الرب، فاعل هذه الأمور","15:18":"المعروفة لديه منذ الأزل.","15:19":"لذلك أرى أن لا نضع عبئا على المهتدين إلى الله من غير اليهود،","15:20":"بل نكتب إليهم رسالة نوصيهم فيها بأن يمتنعوا عن الأكل من الذبائح النجسة المقربة للأصنام، وعن ارتكاب الزنى، وعن تناول لحوم الحيوانات المخنوقة، وعن الدم.","15:21":"فإن لموسى، منذ القدم، أتباعا في كل مدينة، يقرأون شريعته ويبشرون بها في المجامع كل سبت».","15:22":"عند ذلك أجمع الرسل والشيوخ والجماعة كلها على اختيار رجلين من الإخوة يرسلونهما إلى أنطاكية مع بولس وبرنابا. فاختاروا يهوذا، الملقب برسابا، وسيلا، وكان لهما مكانة رفيعة بين الإخوة.","15:23":"وسلموهم هذه الرسالة: «من الرسل والشيوخ والإخوة، إلى الإخوة المؤمنين من غير اليهود في مقاطعات أنطاكية وسورية وكيليكية: سلام!","15:24":"علمنا أن بعض الأشخاص ذهبوا من عندنا إليكم، دون تفويض منا فأثاروا بكلامهم الاضطراب بينكم وأقلقوا أفكاركم.","15:25":"،","15:26":"فأجمعنا برأي واحد على أن نختار رجلين قد كرسا حياتهما لاسم ربنا يسوع المسيح نرسلهما إليكم مع أخوينا الحبيبين برنابا وبولس.","15:27":"فأرسلنا يهوذا وسيلا، ليبلغاكم الرسالة نفسها شفاها.","15:28":"فقد رأى الروح القدس ونحن، أن لا نحملكم أي عبء فوق ما يتوجب عليكم.","15:29":"إنما عليكم أن تمتنعوا عن الأكل من الذبائح المقربة للأصنام، وعن تناول الدم ولحوم الحيوانات المخنوقة، وعن ارتكاب الزنى. وتحسنون عملا إن حفظتم أنفسكم من هذه الأمور. عافاكم الله!»","15:30":"فانطلق حاملو الرسالة، وسافروا إلى أنطاكية، حيث دعوا الجماعة إلى الاجتماع، وقدموا إليهم الرسالة.","15:31":"ولما قرأوها فرحوا بما فيها من تشجيع.","15:32":"وكان يهوذا وسيلا نبيين أيضا، فوعظا الإخوة كثيرا، وشددا عزيمتهم.","15:33":"وبعد مدة من الزمن صرفهما الإخوة في أنطاكية بسلام إلى الذين أرسلوهما.","15:34":"ولكن سيلا استحسن البقاء في أنطاكية، فعاد يهوذا وحده.","15:35":"وبقي هناك أيضا بولس وبرنابا يعلمان ويبشران بكلمة الرب، يعاونهما آخرون كثيرون.","15:36":"وبعد بضعة أيام قال بولس لبرنابا: «هيا نرجع لنتفقد الإخوة ونطلع على أحوالهم في كل مدينة بشرنا فيها بكلمة الرب».","15:37":"فاقترح برنابا أن يأخذا معهما يوحنا الملقب مرقس.","15:38":"ولكن بولس رفض أن يأخذاه معهما، لأنه كان قد فارقهما في بمفيلية، ولم يرافقهما في الخدمة.","15:39":"فوقعت بينهما مشاجرة حتى انفصل أحدهما عن الآخر. فأخذ برنابا مرقس وسافر بحرا إلى قبرص،","15:40":"واختار بولس أن يرافقه سيلا. فاستودعه الإخوة إلى نعمة الله،","15:41":"فسافر في مقاطعتي سورية وكيليكية يشدد الكنائس.","16:1":"ووصل بولس إلى دربة، ثم إلى لسترة، وكان فيها تلميذ اسمه تيموثاوس، أمه يهودية كانت قد آمنت بالمسيح، وأبوه يوناني.","16:2":"وكان الإخوة في لسترة وإيقونية يشهدون لتيموثاوس شهادة حسنة.","16:3":"فأحب بولس أن يصحبه في رحلته. ولأن يهود تلك المنطقة كانوا يعرفون أن أباه يوناني، فقد أخذه بولس وختنه.","16:4":"وأخذ بولس ورفاقه ينتقلون من مدينة إلى أخرى، يبلغون المؤمنين التوصيات التي أقرها الرسل والشيوخ في أورشليم، لكي يعملوا بها.","16:5":"فكانت الكنائس تتقوى في الإيمان، ويزداد عددها يوما بعد يوم.","16:6":"ومنعهم الروح القدس من التبشير في مقاطعة أسيا، فسافروا في مقاطعتي فريجية وغلاطية.","16:7":"ولما وصلوا حدود مقاطعة ميسيا، اتجهوا نحو مقاطعة بيثينية، ولكن روح يسوع لم يسمح لهم بالدخول إليها،","16:8":"فتوجهوا إلى مدينة ترواس مرورا بميسيا.","16:9":"وفي تلك الليلة رأى بولس في رؤيا رجلا من أهل مقدونية يتوسل إليه ويقول: «اعبر إلى مقدونية وأنجدنا!»","16:10":"عندئذ تأكدنا أن الرب دعانا للتبشير في مقدونية. فاتجهنا إليها في الحال.","16:11":"فأبحرنا من ميناء ترواس إلى جزيرة ساموثراكي. وفي اليوم التالي تابعنا السفر إلى ميناء نيابوليس،","16:12":"ومنها إلى مدينة فيلبي، وهي كبرى مدن مقاطعة مقدونية، ومستعمرة للرومان. فبقينا فيها بضعة أيام.","16:13":"وفي يوم السبت ذهبنا إلى ضفة نهر في إحدى ضواحي المدينة حيث جرت العادة أن تقام الصلاة. فجلسنا نكلم النساء المجتمعات،","16:14":"ومن بينهن تاجرة أرجوان من مدينة ثياتيرا، متعبدة لله، اسمها ليدية، كانت تسمع ففتح الله قلبها لتقبل كلام بولس.","16:15":"فلما تعمدت هي وأهل بيتها، دعتنا بإلحاح لقبول ضيافتها قائلة: «إن كنتم قد حكمتم أني مؤمنة بالرب، فانزلوا ضيوفا ببيتي». فاضطرتنا إلى قبول دعوتها.","16:16":"وذات يوم كنا ذاهبين إلى الصلاة، فالتقت بنا خادمة يسكنها روح عرافة، كانت تكسب سادتها ربحا كثيرا من عرافتها،","16:17":"فأخذت تسير وراء بولس ووراءنا صارخة: «هؤلاء الناس هم عبيد الله العلي، يعلنون لكم طريق الخلاص».","16:18":"وظلت تفعل هذا أياما كثيرة، حتى تضايق بولس كثيرا، فالتفت وقال للروح الذي فيها: «باسم يسوع المسيح، آمرك أن تخرج منها!» فخرج حالا.","16:19":"ولما رأى سادتها أن مورد رزقهم قد انقطع، قبضوا على بولس وسيلا، وجروهما إلى ساحة المدينة للمحاكمة،","16:20":"وقدموهما إلى الحكام قائلين: «هذان الرجلان يثيران الفوضى في المدينة؛ فهما يهوديان","16:21":"يناديان بتقاليد لا يجوز لنا نحن الرومانيين أن نقبلها أو نعمل بها!»","16:22":"فثار الجمع عليهما، ومزق الحكام ثيابهما وأمروا بجلدهما،","16:23":"فجلدوهما كثيرا وألقوهما في السجن، وأمروا ضابط السجن بتشديد الحراسة عليهما.","16:24":"ونفذ ضابط السجن هذا الأمر المشدد. فزج بهما في السجن الداخلي، وأدخل أرجلهما في مقطرة خشبية.","16:25":"ونحو منتصف الليل كان بولس وسيلا يصليان ويسبحان الله، والمسجونون يسمعونهما،","16:26":"وفجأة حدث زلزال شديد هز أركان السجن، فانفتحت جميع أبوابه حالا، وسقطت قيود السجناء كلهم.","16:27":"وأيقظ الزلزال ضابط السجن. فلما رأى الأبواب مفتوحة ظن أن السجناء هربوا، فاستل سيفه ليقتل نفسه،","16:28":"ولكن بولس صاح به بأعلى صوته: «لا تمس نفسك بسوء، فنحن جميعا هنا!»","16:29":"فطلب ضوءا، واندفع إلى الداخل وهو يرتجف خوفا، وارتمى أمام بولس وسيلا،","16:30":"ثم أخرجهما خارجا وسألهما: «يا سيدي، ماذا ينبغي أن أفعل لكي أخلص؟»","16:31":"فأجاباه: «آمن بالرب يسوع فتخلص أنت وأهل بيتك!»","16:32":"ثم بشراه وأهل بيته جميعا بكلمة الرب.","16:33":"فأخذهما في تلك الساعة من الليل وغسل جراحهما وتعمد حالا هو وأهل بيته جميعا.","16:34":"ثم ذهب بهما إلى بيته وبسط لهما مائدة. وابتهج مع أهل بيته جميعا، إذ كان قد آمن بالله.","16:35":"ولما طلع الصباح أرسل الحكام بعض رجال الشرطة ليبلغوا ضابط السجن أمر الإفراج عن بولس وسيلا.","16:36":"فأخبر الضابط بولس بالأمر، قائلا: «أرسل الحكام أمرا بالإفراج عنكما فاخرجا الآن واذهبا بسلام!»","16:37":"فاحتج بولس قائلا: «جلدونا أمام الناس بغير محاكمة، مع أننا نحمل الجنسية الرومانية، وزجوا بنا في السجن. فكيف يطلقون سراحنا الآن سرا! كلا! بل ليأتوا هم ويطلقوا سراحنا!»","16:38":"وأخبر رجال الشرطة الحكام بهذا الاعتراض، فخافوا حين علموا أنهما رومانيان،","16:39":"فجاءوا يعتذرون إليهما، وأطلقوهما طالبين إليهما أن يغادرا المدينة.","16:40":"فخرج بولس وسيلا من السجن وتوجها إلى بيت ليدية، حيث قابلا الإخوة وشجعاهم، ثم غادرا المدينة.","17:1":"وصل بولس وسيلا إلى تسالونيكي بعدما مرا بأمفيبوليس وأبولونية. وكان في تسالونيكي مجمع لليهود.","17:2":"فذهب إليه كعادته، وناقشهم لثلاثة سبوت، مستندا إلى الكتاب،","17:3":"وشرح لهم مبينا أن المسيح كان لابد أن يتألم ويقوم من بين الأموات، وأن «المسيح الذي تنتظرونه هو يسوع الذي أبشركم به الآن!»","17:4":"فاقتنع بعض الحاضرين وانضموا إلى بولس وسيلا. وكان بينهم عدد كبير من اليونانيين المتعبدين لله وكثيرات من النساء النبيلات.","17:5":"فأثار ذلك حسد اليهود الذين لم يؤمنوا، فأتوا ببعض الأشرار من أبناء الشارع، وجمعوا جمهورا وأخذوا يحرضون الناس حتى أثاروا الفوضى في المدينة، ثم هجموا على بيت ياسون مطالبين بتسليم بولس وسيلا إلى الجمع.","17:6":"ولما لم يجدوهما هناك جروا ياسون وبعض الإخوة واقتادوهم إلى حكام المدينة، واشتكوا عليهم صارخين: «إن هذين الرجلين اللذين قلبا الدنيا، قد جاءا إلى مدينتنا أيضا،","17:7":"فاستضافهما ياسون. وهم جميعا يخالفون أوامر القيصر، وينادون بملك آخر اسمه يسوع».","17:8":"فأحدثوا انزعاجا لدى الجمع والحكام عندما سمعوا هذا.","17:9":"فقبض الحكام كفالة من ياسون ومن معه ثم أفرجوا عنهم.","17:10":"وفي الليل رحل الإخوة بولس وسيلا حالا إلى بيرية. ولما وصلا إليها، ذهبا إلى مجمع اليهود فيها.","17:11":"وكان يهود بيرية أشرف من يهود تسالونيكي، فقبلوا كلمة الله برغبة شديدة، وأخذوا يدرسون الكتاب يوميا ليتأكدوا من صحة التعليم.","17:12":"فآمن عدد كبير منهم، كما آمن من اليونانيين نساء نبيلات وعدد كبير من الرجال.","17:13":"وعرف يهود تسالونيكي أن بولس يبشر بكلمة الله في بيرية، فلحقوا به وبدأوا يحرضون الجموع ليثوروا عليه.","17:14":"وفي الحال أخذ بعض الإخوة بولس نحو البحر ليسافر، وبقي سيلا وتيموثاوس هناك.","17:15":"ورافق الإخوة بولس حتى أوصلوه إلى أثينا، ثم رجعوا بعدما أوصاهم بولس بأن يلحق به سيلا وتيموثاوس بأسرع ما يمكن.","17:16":"وبينما كان بولس ينتظرهما في أثينا رأى المدينة مملوءة أصناما فتضايقت روحه.","17:17":"وأخذ يخاطب اليهود وغيرهم من المتعبدين في المجمع، ومن يلقاهم كل يوم في ساحة المدينة.","17:18":"وجرت مناقشة بينه وبين بعض الفلاسفة الأبيقوريين والرواقيين. ولما وجدوا أنه يبشر بيسوع والقيامة من الموت قال بعضهم: «ماذا يعني هذا المدعي الأحمق بكلامه؟» وقال آخرون: «يبدو أنه ينادي بآلهة غريبة».","17:19":"ثم قادوه إلى تلة أريوباغوس (حيث مجلس المدينة) وسألوه: «هل لنا أن نعرف ما هو المذهب الجديد الذي تنادي به؟","17:20":"إننا نسمع منك أقوالا غريبة نريد أن نعرف معناها».","17:21":"وكان أهل أثينا والأجانب الساكنون فيها لا يمضون أوقات فراغهم إلا في مناقشة الأفكار الجديدة.","17:22":"فوقف بولس في وسط الأريوباغوس، وقال: «يا أهل أثينا، أراكم متدينين كثيرا في كل أمر.","17:23":"فبينما كنت أتجول في مدينتكم وأنظر إلى معابدكم وجدت معبدا مكتوبا عليه «إلى الإله المجهول». فبهذا الإله الذي تعبدونه ولا تعرفونه، أنا أبشركم.","17:24":"إنه الله الذي خلق الكون وكل ما فيه، وهو الذي لا يسكن في معابد بنتها أيدي البشر، لأنه رب السماء والأرض،","17:25":"وليس بحاجة إلى خدمة يقدمها له الناس. فإنه يهب جميع الخلق الحياة والنفس وكل شيء.","17:26":"وقد أخرج الشعوب جميعا من أصل واحد، وأسكنهم بلاد الأرض كلها، وحدد مسبقا أزمنة وجودهم وحدود أوطانهم،","17:27":"لكي يبحثوا عن الله لعلهم يتلمسونه فيهتدوا إليه! فإنه ليس بعيدا عن أي واحد منا،","17:28":"لأننا به نحيا ونتحرك ونوجد، أو كما قال بعض شعرائكم: نحن أيضا ذريته!","17:29":"فما دمنا ذرية الله، فيجب ألا ننظر إلى الألوهية كأنها صنم من ذهب أو فضة أو حجر يستطيع إنسان أن ينحته أو يصوغه كما يتخيل!","17:30":"فالله الآن يدعو جميع الناس في كل مكان أن يرجعوا إليه تائبين، وقد غض النظر عن أزمنة الجهل التي مرت،","17:31":"لأنه حدد يوما يدين فيه العالم بالعدل على يد رجل اختاره لذلك. وقد قدم للجميع برهانا، إذ أقامه من بين الأموات».","17:32":"وما إن سمع الحاضرون بالقيامة من بين الأموات حتى بدأ بعضهم يستهزئون. ولكن آخرين قالوا لبولس: «نود أن تحدثنا في هذا الموضوع ثانية».","17:33":"وهكذا خرج بولس من بينهم.","17:34":"ولكن بعضهم انضموا إلى بولس وآمنوا ومنهم ديونيسيوس، وكان عضوا في مجلس أريوباغوس، وامرأة اسمها داماريس، وآخرون غيرهما.","18:1":"بعد ذلك ترك بولس أثينا، وسافر إلى مدينة كورنثوس.","18:2":"فالتقى هناك بيهودي اسمه أكيلا، من مواليد بنطس، كان قد جاء حديثا مع زوجته بريسكلا من إيطالية، لأن القيصر كلوديوس أمر بطرد اليهود من روما، فقصد بولس إليهما.","18:3":"وإذ كان من أهل مهنتهما، وهي صناعة الخيام، أقام عندهما وكان يشتغل معهما.","18:4":"وكان في كل سبت يناقش الحاضرين في المجمع لإقناع اليهود واليونانيين.","18:5":"ولما وصل سيلا وتيموثاوس من مقاطعة مقدونية، تفرغ بولس تماما للتبشير، شاهدا لليهود أن يسوع هو المسيح.","18:6":"ولكنهم عارضوا شهادته وأخذوا يشتمون. فما كان منه إلا أن نفض ثوبه وقال لهم: «دمكم على رؤوسكم. أنا بريء! ومنذ الآن أتوجه لتبشير غير اليهود».","18:7":"ثم ترك بولس مكان إقامته، ونزل ضيفا ببيت رجل غير يهودي يتعبد لله، اسمه تيطس يوستس، كان بيته ملاصقا للمجمع.","18:8":"فآمن كريسبس رئيس المجمع بالرب، هو وأهل بيته جميعا. وسمع كثيرون من أهل كورنثوس تبشير بولس، فآمنوا وتعمدوا.","18:9":"وذات ليلة رأى بولس الرب في رؤيا يقول له: «لا تخف، بل تكلم ولا تسكت،","18:10":"فأنا معك، ولن يقدر أحد أن يؤذيك، لأن لي شعبا كثيرا في هذه المدينة».","18:11":"فبقي بولس في كورنثوس سنة وستة أشهر يعلم الناس كلمة الله.","18:12":"ولما كان الحاكم الروماني غاليون يتولى الحكم على بلاد أخائية، تجمع اليهود ضد بولس برأي واحد، وساقوه إلى المحكمة،","18:13":"واشتكوا عليه قائلين: «هذا الرجل يحاول إقناع الناس بأن يعبدوا الله بطريقة تخالف شريعتنا».","18:14":"وكاد بولس أن يبدأ دفاعه لولا أن غاليون قال لليهود: «أيها اليهود، لو كانت القضية جريمة أو ذنبا، لكنت أحتملكم كما يقضي العدل.","18:15":"ولكن مادامت القضية جدلا في ألفاظ وأسماء وفي شريعتكم، فعليكم أن تعالجوها بأنفسكم. أنا لا أريد أن أحكم في هذه القضايا!»","18:16":"ثم طردهم من المحكمة،","18:17":"فأخذوا سوستانيس رئيس المجمع وضربوه أمام المحكمة، ولكن غاليون لم يهمه شيء من ذلك!","18:18":"وبقي بولس في كورنثوس فترة طويلة، ثم ودع الإخوة وسافر بحرا متجها إلى سورية ومعه بريسكلا وأكيلا، بعدما حلق رأسه في مدينة كنخريا، إذ كان عليه نذر.","18:19":"فلما وصلوا إلى أفسس تركهما بولس فيها، ودخل مجمع اليهود وخطب فيهم.","18:20":"فطلبوا منه أن يقضي عندهم فترة أطول، فلم يقبل،","18:21":"وودعهم قائلا: «سأعود إليكم إن شاء الله!» ثم سافر بحرا من أفسس،","18:22":"ونزل في ميناء قيصرية فصعد وسلم على الكنيسة، ثم نزل إلى مدينة أنطاكية،","18:23":"فأمضى فيها بعض الوقت. ثم طاف مقاطعتي غلاطية وفريجية منتقلا من بلدة إلى أخرى وهو يشدد عزيمة التلاميذ جميعا.","18:24":"وجاء إلى أفسس يهودي اسمه أبلوس، إسكندري المولد، فصيح اللسان، خبير في الكتاب.","18:25":"كان قد تلقن طريق الرب. فبدأ يخطب بحماسة شديدة، ويعلم الحقائق المختصة بيسوع تعليما صحيحا. ومع أنه لم يكن يعرف سوى معمودية يوحنا،","18:26":"فقد أخذ يتكلم في المجمع بجرأة. فسمعه أكيلا وبريسكلا، فأخذاه إليهما وأوضحا له طريق الله بأكثر دقة.","18:27":"وقرر أبلوس أن يسافر إلى بلاد أخائية فشجعه الإخوة وكتبوا إلى التلاميذ هناك أن يرحبوا به. ولما وصل إلى هناك أعان الذين كانوا قد آمنوا إعانة كبرى بما له من النعمة:","18:28":"فقد كان جريئا في مجادلاته العلنية مع اليهود، وكان يفحمهم مستندا إلى الكتاب فيثبت أن يسوع هو المسيح.","19:1":"وبينما كان أبلوس في كورنثوس وصل بولس إلى أفسس، بعدما مر بالمناطق الداخلية من البلاد. وهناك وجد بعض التلاميذ،","19:2":"فسألهم: «هل نلتم الروح القدس عندما آمنتم؟» أجابوه: «لا! حتى إننا لم نسمع بوجود الروح القدس!»","19:3":"فسأل: «إذن على أي أساس قد تعمدتم؟» أجابوا: «على أساس معمودية يوحنا!»","19:4":"فقال بولس: «كان يوحنا يعمد بمعمودية التوبة، ويدعو الشعب إلى الإيمان بالآتي بعده، أي بيسوع».","19:5":"فلما سمعوا هذا تعمدوا باسم الرب يسوع.","19:6":"وما إن وضع بولس يديه عليهم حتى حل عليهم الروح القدس، وأخذوا يتكلمون بلغات أخرى ويتنبأون.","19:7":"وكان عددهم نحو اثني عشر رجلا.","19:8":"وأخذ بولس يداوم على الذهاب إلى المجمع مدة ثلاثة أشهر، يتكلم بجرأة فيناقش الحاضرين ويحاول إقناعهم بالحقائق المختصة بملكوت الله.","19:9":"ولكن بعضهم عاندوا ولم يقتنعوا، وأخذوا يشتمون هذا الطريق أمام المجتمعين. فانفصل بولس عنهم، وانفرد بالتلاميذ، وبدأ يعقد مناقشات كل يوم في مدرسة رجل اسمه تيرانوس،","19:10":"وداوم على ذلك مدة سنتين. وهكذا وصلت كلمة الرب إلى جميع سكان مقاطعة أسيا من اليهود واليونانيين.","19:11":"وكان الله يجري معجزات خارقة على يد بولس،","19:12":"حتى صار الناس يأخذون المناديل أو المآزر التي مست جسده، ويضعونها على المرضى، فتزول أمراضهم وتخرج الأرواح الشريرة منهم.","19:13":"وحاول بعض اليهود الجوالين الذين يحترفون طرد الأرواح الشريرة، أن يستغلوا اسم الرب يسوع، قائلين: «نطردك باسم يسوع الذي يبشر به بولس!»","19:14":"وكان بين هؤلاء سبعة أبناء لواحد من الكهنة اسمه سكاوا،","19:15":"فأجابهم الروح الشرير: «يسوع أنا أعرفه، وبولس أفهمه. ولكن، من أنتم؟»","19:16":"ثم هجم عليهم الرجل الذي به الروح الشرير، فتمكن منهم وغلبهم، فهربوا من البيت الذي كانوا فيه، عراة مجرحين.","19:17":"فانتشر خبر ذلك بين اليهود واليونانيين الساكنين في أفسس، فاستولت الرهبة على الجميع. وتمجد اسم الرب يسوع.","19:18":"فجاء كثيرون من الذين كانوا قد آمنوا يعترفون ويخبرون بما كانوا يعملون.","19:19":"وأخذ كثيرون من المشتغلين بالسحر يجمعون كتبهم ويحرقونها أمام الجميع. وقد حسب ثمنها، فتبين أنه خمسون ألف قطعة من الفضة.","19:20":"بهذه الصورة كانت كلمة الرب تنتشر وتقوى باقتدار.","19:21":"وبعد حدوث هذه الأمور، عزم بولس على السفر إلى أورشليم مرورا بمقاطعتي مقدونية وأخائية، قائلا: «لابد لي بعد إقامتي فيها من زيارة روما أيضا!»","19:22":"فأرسل إلى مقدونية اثنين من معاونيه، هما تيموثاوس وأرسطوس، وبقي مدة من الزمن في مقاطعة أسيا.","19:23":"في تلك المدة وقع اضطراب خطير في أفسس بسبب هذا الطريق.","19:24":"فإن صائغا اسمه ديمتريوس كان يصنع نماذج فضية صغيرة لمعابد الإلهة أرطاميس، فيعود ذلك عليه وعلى عماله بربح وفير،","19:25":"دعا عماله وأهل مهنته، وقال لهم: «تعلمون أيها الرجال أن عيشنا الرغيد يعتمد على صناعتنا هذه،","19:26":"وقد رأيتم وسمعتم أن بولس هذا أضل عددا كبيرا من الناس، لا في أفسس وحدها، بل في مقاطعة أسيا كلها تقريبا، وأقنعهم بأن الآلهة التي تصنعها الأيدي ليست بآلهة.","19:27":"وهذا لا يهدد صناعتنا بالكساد وحسب، بل يعرض معبد أرطاميس إلهتنا العظمى لفقدان هيبته. فنخشى أن تتلاشى كرامتها وتنهار عظمتها، وهي التي يتعبد لها سكان أسيا جميعا، بل العالم كله!»","19:28":"فلما سمع العمال هذا الكلام تملكهم الغضب وبدأوا يصرخون: «عظيمة أرطاميس إلهة أهل أفسس!»","19:29":"وعم الاضطراب المدينة كلها. وهجم حشد كبير من الناس على غايوس وأرسترخس المقدونيين رفيقي بولس في السفر، وجروهما إلى ساحة الملعب.","19:30":"وأراد بولس أن يواجه الجمهور، ولكن التلاميذ منعوه من ذلك،","19:31":"كما أرسل إليه أصدقاؤه من وجهاء أسيا يرجون منه ألا يعرض نفسه لخطر الذهاب إلى الملعب،","19:32":"فقد كان الأمر مختلطا على الجمهور، بعضهم يصرخ بشيء، وبعضهم يصرخ بشيء آخر، حتى إن أكثرهم لم يكونوا يعرفون سبب تجمعهم.","19:33":"وكان بين الجمهور يهودي اسمه إسكندر، دفعه اليهود إلى الأمام، ودعاه بعضهم إلى الكلام. فأشار بيده يريد أن يلقي على الشعب كلمة دفاع.","19:34":"لكن المحتشدين عرفوا أنه يهودي، فأخذوا يهتفون معا هتافا واحدا ظلوا يرددونه نحو ساعتين: «عظيمة أرطاميس إلهة أهل أفسس!»","19:35":"أخيرا تمكن كاتب المدينة من تهدئة الحشود، وقال: «يا أهل أفسس، من ينكر أن أفسس هي المدينة الحارسة لهيكل أرطاميس الإلهة العظيمة، ولصنمها الذي هبط من السماء؟","19:36":"فلأنه لا خلاف في هذا الأمر، يجب أن تهدأوا ولا تفعلوا شيئا بتسرع.","19:37":"فقد أحضرتم هذين الرجلين، مع أنهما لم يسرقا المعبد ولم يشتما إلهتكم.","19:38":"أما إذا كان لديمتريوس وزملاء مهنته شكوى، فإن عندنا محاكم وقضاة. فليتقدموا بشكواهم إلى القضاة.","19:39":"وإذا كان لكم شكوى أخرى، فإن النظر فيها يتم في جلسة قانونية.","19:40":"أما الآن فكلنا معرضون للمحاكمة بتهمة افتعال الاضطراب، بسبب ما حدث اليوم، ونحن لا نملك حجة نبرر بها التجمع!»","19:41":"وبقوله هذا صرف المحتشدين.","20:1":"بعدما انتهى الاضطراب، دعا بولس التلاميذ وشجعهم، ثم ودعهم وسافر إلى مقاطعة مقدونية،","20:2":"وتجول فيها يعظ ويشجع التلاميذ في كل مكان. وأخيرا وصل إلى اليونان،","20:3":"وقضى فيها ثلاثة أشهر. وبينما كان يستعد للسفر بحرا إلى سورية، عرف أن اليهود يدبرون مؤامرة لقتله. فقرر أن يعود بطريق مقدونية.","20:4":"ورافقه في السفر سوباترس بن برس من بيرية؛ وأرسترخس وسكوندس من تسالونيكي؛ وغايوس وتيموثاوس من دربة، وتيخيكس وتروفيمس من مقاطعة أسيا.","20:5":"هؤلاء سبقونا مع بولس وانتظرونا في ترواس.","20:6":"وبعد عيد الفطير اليهودي سافرنا نحن من فيلبي، بطريق البحر، فوصلنا ترواس بعد خمسة أيام، فلحقنا بهم، وبقينا هناك سبعة أيام.","20:7":"وفي أول يوم من الأسبوع، إذ اجتمعنا لنكسر الخبز، أخذ بولس يعظ المجتمعين. ولما كان ينوي السفر في اليوم التالي، أطال وعظه إلى منتصف الليل.","20:8":"وكان اجتماعنا في غرفة بالطبقة العليا، وقد أشعلت فيها مصابيح كثيرة.","20:9":"وكان شاب اسمه أفتيخوس قد جلس على النافذة، فغلب عليه النوم العميق، وبولس ماض في حديثه الطويل، فسقط من الطبقة الثالثة وحمل ميتا.","20:10":"فنزل بولس وارتمى عليه، وطوقه بذراعيه وقال: «لا تقلقوا! ماتزال حياته فيه!»","20:11":"وبعدما صعد بولس وكسر الخبز وأكل، ثم تابع حديثه إلى الفجر، سافر برا (إلى أسوس).","20:12":"أما الشاب فجاءوا به حيا، فكان لهم في ذلك عزاء عظيم.","20:13":"وأما نحن فسبقنا بولس وتوجهنا إلى أسوس بطريق البحر، حيث انتظرنا وصوله حسب الخطة التي كان قد رسمها بأن يوافينا سيرا على قدميه.","20:14":"فلما لحق بنا، أصعدناه إلى السفينة، وأبحرنا إلى ميناء ميتيليني","20:15":"وتابعنا السفر فوصلنا في اليوم التالي أمام جزيرة خيوس. وفي اليوم الثالث مررنا بالقرب من جزيرة ساموس، ووصلنا ميليتس في اليوم الرابع.","20:16":"وكان بولس قد قرر أن يتجاوز أفسس في البحر لكي لا يتأخر في مقاطعة أسيا، فقد كان يريد السرعة لعله يتمكن من الوصول إلى أورشليم في يوم الخمسين.","20:17":"ومن ميليتس أرسل بولس إلى أفسس يستدعي شيوخ الكنيسة.","20:18":"فلما جاءوا إليه، قال لهم: «تعلمون كيف كان تصرفي معكم طوال المدة التي قضيتها بينكم، منذ أول يوم دخلت فيه مقاطعة أسيا.","20:19":"فقد كنت أخدم الرب بكل تواضع، وبكثير من الدموع، وأنا أعاني المحن التي أصابتني بها مؤامرات اليهود.","20:20":"وما قصرت في شيء يمكن أن يعود عليكم بالفائدة إلا وكنت أعلنه لكم وأعلمكم به علنا ومن بيت إلى بيت.","20:21":"فكنت أحث اليهود واليونانيين على أن يتوبوا إلى الله ويؤمنوا بربنا يسوع.","20:22":"وأنا اليوم ذاهب إلى أورشليم، مدفوعا بالروح، ولا أعلم ماذا ينتظرني هناك.","20:23":"إلا أن الروح القدس كان يعلن لي في كل مدينة أذهب إليها أن السجن والمصاعب تنتظرني","20:24":"ولكني لا أحسب لحياتي أية قيمة، ما دمت أسعى إلى بلوغ غايتي وإتمام الخدمة التي كلفني إياها الرب يسوع: أن أشهد ببشارة نعمة الله.","20:25":"وأنا أعلم أنكم لن تروا وجهي بعد اليوم، أنتم الذين تجولت بينكم جميعا مبشرا بملكوت الله.","20:26":"لذلك أشهد لكم اليوم أني بريء من دمكم جميعا،","20:27":"لأني لم أمتنع عن إبلاغكم جميع مقاصد الله.","20:28":"فاسهروا إذن على أنفسكم وعلى جميع القطيع الذي عينكم بينه الروح القدس نظارا، لترعوا كنيسة الله التي اشتراها بدمه.","20:29":"فإني أعلم أنه بعد رحيلي سيندس بينكم ذئاب خاطفة، لا تشفق على القطيع.","20:30":"بل إن قوما منكم أنتم سيقومون ويعلمون تعاليم منحرفة، ليجروا التلاميذ وراءهم.","20:31":"لذلك كونوا متيقظين، وتذكروا أني، مدة ثلاث سنين، لم أتوقف ليلا ونهارا عن نصح كل واحد منكم وأنا أذرف الدموع.","20:32":"والآن أسلمكم إلى الله وإلى كلمة نعمته القادرة أن تبنيكم وتعطيكم ميراثا تشتركون فيه مع جميع المقدسين لله.","20:33":"ما اشتهيت يوما فضة ولا ذهبا ولا ثوبا من عند أحد.","20:34":"وأنتم تعلمون أني اشتغلت بيدي هاتين لأسد حاجاتي وحاجات مرافقي.","20:35":"وقد أظهرت لكم بوضوح كيف يجب أن نبذل الجهد لنساعد المحتاجين، متذكرين كلمات الرب يسوع، إذ قال: الغبطة في العطاء أكثر مما في الأخذ!»","20:36":"وبعد هذا الكلام ركع بولس معهم جميعا وصلى.","20:37":"وبكى الجميع كثيرا، وعانقوا بولس وقبلوه بحرارة.","20:38":"وقد حزنوا كثيرا، خاصة لأنه قال لهم إنهم لن يروا وجهه مرة أخرى. ثم رافقوه إلى السفينة مودعين.","21:1":"وبعدما انسلخنا عنهم، أبحرنا على خط مستقيم باتجاه كوس. وفي اليوم التالي وصلنا إلى جزيرة رودس، ومنها اتجهنا إلى ميناء باترا،","21:2":"حيث وجدنا سفينة مسافرة إلى ساحل فينيقية، فركبناها وأقلعنا.","21:3":"ولاحت لنا جزيرة قبرص فجاوزناها عن شمالنا، وتابعنا السفر باتجاه سورية، فوصلنا إلى ميناء صور ونزلنا فيها، لأن السفينة كانت ستفرغ حمولتها هناك.","21:4":"عندئذ بحثنا عن التلاميذ، وأقمنا عندهم سبعة أيام، وكانوا ينصحون بولس، بإلهام من الروح، ألا يصعد إلى أورشليم.","21:5":"وعندما انتهت مدة إقامتنا عندهم خرجنا لنكمل سفرنا، فرافقونا مع نسائهم وأولادهم إلى خارج المدينة مودعين. فركعنا على الشاطئ وصلينا،","21:6":"ثم ودعنا بعضنا بعضا، وركبنا السفينة، فعادوا هم إلى بيوتهم.","21:7":"وتابعنا السفر بحرا من صور إلى بتولمايس، فسلمنا على الإخوة هناك وقضينا معهم يوما واحدا.","21:8":"وفي اليوم التالي ذهبنا إلى مدينة قيصرية ونزلنا ضيوفا ببيت المبشر فيلبس، وهو واحد من المدبرين السبعة،","21:9":"وله أربع بنات عذارى كن يتنبأن.","21:10":"فبقينا عنده عدة أيام. وبينما نحن هناك جاءنا من منطقة اليهودية نبي اسمه أغابوس.","21:11":"فأخذ حزام بولس، وقيد نفسه رابطا يديه ورجليه وقال: «يقول الروح القدس إن صاحب هذا الحزام سيقيده اليهود هكذا في أورشليم، ويسلمونه إلى أيدي الأجانب».","21:12":"فلما سمعنا هذا بدأنا جميعا، نحن مرافقي بولس والمؤمنين من أهل البلدة، نرجو من بولس ألا يذهب إلى أورشليم،","21:13":"ولكنه قال لنا: «ما لكم تبكون وتحطمون قلبي؟ إني مستعد ليس فقط لأن أقيد في أورشليم، بل أيضا لأن أموت من أجل اسم الرب يسوع!»","21:14":"ولما لم نتمكن من إقناعه سكتنا، وقلنا: «فلتكن مشيئة الرب!»","21:15":"وبعد مدة تأهبنا للسفر واتجهنا إلى أورشليم","21:16":"بصحبة بعض التلاميذ من قيصرية، فأخذونا إلى بيت مناسون القبرصي، وهو تلميذ قديم، فنزلنا عليه ضيوفا.","21:17":"ولدى وصولنا إلى أورشليم، رحب بنا الإخوة فرحين.","21:18":"وفي اليوم التالي لوصولنا رافقنا بولس للاجتماع بيعقوب، وكان الشيوخ كلهم مجتمعين عنده.","21:19":"فسلم بولس عليهم وأخذ يخبرهم على التوالي بكل ما فعله الله بين غير اليهود بواسطة خدمته.","21:20":"فلما سمعوا أخباره مجدوا الله، وقالوا له: «أنت ترى أيها الأخ أن الذين آمنوا بالرب من اليهود يعدون بالآلاف، وهم متحمسون للشريعة،","21:21":"وقد سمعوا بأنك تدعو اليهود الذين يسكنون بين الأجانب إلى الارتداد عن موسى، وتوصيهم بألا يختنوا أولادهم ولا يتبعوا العادات المتوارثة،","21:22":"فما العمل إذن، لأنهم لابد أن يسمعوا بقدومك؟","21:23":"فاعمل ما نقوله لك: عندنا أربعة رجال عليهم نذر،","21:24":"فخذهم إلى الهيكل وتطهر معهم، وادفع نفقة حلق رؤوسهم، فيعرف الجميع أن ما سمعوه عنك غير صحيح، وأنك تسلك مثلهم طريق العمل بالشريعة.","21:25":"أما المؤمنون الذين من غير اليهود، فقد أرسلنا إليهم رسالة نوصيهم فيها بأن يمتنعوا عن الأكل من الذبائح المقربة للأصنام، وعن تناول الدم، وعن الأكل من لحوم الحيوانات المخنوقة، وعن الزنى».","21:26":"وهكذا كان. ففي اليوم التالي أخذ بولس الرجال الأربعة؛ وبعدما تطهر معهم، دخل الهيكل لكي يسجل التاريخ الذي ينتهي فيه أسبوع التطهر، حتى تقدم عن كل واحد منهم التقدمة الواجبة.","21:27":"ولما كادت الأيام السبعة أن تنقضي، رأى بعض اليهود من مقاطعة أسيا بولس في الهيكل، فحرضوا الجمع كله، وقبضوا عليه،","21:28":"وهم يصرخون: «النجدة يا بني إسرائيل! هذا هو الرجل الذي يدعو الناس في كل مكان إلى عقيدة تشكل خطرا على شعبنا وشريعتنا وعلى هذا المكان، حتى إنه أدخل اليونانيين إلى الهيكل ودنس هذا المكان المقدس!»","21:29":"فإنهم كانوا قد رأوا تروفيمس الأفسسي مع بولس في المدينة، فظنوا أنه أدخله معه إلى الهيكل.","21:30":"عندئذ هاج أهل المدينة جميعا، وهجم الناس على بولس وجروه إلى خارج الهيكل، ثم أغلقت الأبواب حالا.","21:31":"وبينما هم يحاولون أن يقتلوه سمع قائد الكتيبة الرومانية أن الاضطراب عم أورشليم كلها.","21:32":"فأخذ في الحال جماعة من الجنود وقواد المئات وحضر مسرعا. ولما رأى اليهود القائد وجنوده كفوا عن ضرب بولس.","21:33":"فاقترب القائد وألقى القبض عليه، وأمر جنوده أن يقيدوه بسلسلتين، وأخذ يسأل: «من هو، وماذا فعل؟»","21:34":"فأخذ بعضهم ينادون بشيء وبعضهم بشيء آخر. ولما لم يقدر أن يتبين حقيقة الأمر بسبب الهياج، أمر أن يؤخذ بولس إلى المعسكر.","21:35":"ولما وصل به الجنود إلى السلم اضطروا أن يحملوه ليخلصوه من عنف المحتشدين.","21:36":"فقد كان جمهور المحتشدين يتبعونه صارخين: «ليعدم!»","21:37":"وقبل أن يدخل بولس إلى المعسكر قال للقائد باللغة اليونانية: «أيمكن أن أقول لك شيئا؟» فقال القائد: «أتتكلم اليونانية؟","21:38":"إذن لست أنت ذلك المصري الذي أحدث اضطرابا في المدينة منذ مدة، وتزعم أربعة آلاف رجل من القتلة خرج بهم إلى البرية!»","21:39":"فقال بولس: «إنما أنا يهودي من طرسوس، وهي مدينة مشهورة في مقاطعة كيليكية. فأرجو منك أن تسمح لي بأن أكلم الشعب».","21:40":"فأذن له القائد. ووقف بولس على السلم، وأشار بيده إلى الشعب. فلما ساد السكوت، أخذ يخاطبهم باللغة العبرية، قائلا:","22:1":"«أيها الإخوة والآباء، اسمعوا الآن دفاعي عن نفسي».","22:2":"فلما سمعوه يخاطبهم باللغة العبرية ازدادوا هدوءا فقال:","22:3":"أنا رجل يهودي، ولدت في طرسوس الواقعة في مقاطعة كيليكية، ولكني نشأت في هذه المدينة وتعلمت عند قدمي غمالائيل التربية الموافقة تماما لشريعة آبائنا. وكنت غيورا في أمور الله، مثلكم جميعا اليوم.","22:4":"فاضطهدت هذا الطريق حتى الموت، فكنت أعتقل أتباعه من الرجال والنساء، وأزج بهم في السجون.","22:5":"ويشهد رئيس الكهنة ومجلس الشيوخ على صدق كلامي هذا. فقد أخذت منهم رسائل إلى إخوانهم في دمشق ليعاونوني في القبض على الذين هناك، لأسوقهم إلى أورشليم فينالوا عقابهم.","22:6":"ولما وصلت إلى مقربة من دمشق، وكان الوقت نحو الظهر، أضاء حولي فجأة نور باهر،","22:7":"فوقعت على الأرض، وسمعت صوتا يقول لي: شاول، شاول، لماذا تضطهدني؟","22:8":"فأجبت: من أنت يا سيد؟ فقال: أنا يسوع الناصري الذي أنت تضطهده.","22:9":"وقد رأى مرافقي النور، ولكنهم لم يسمعوا صوت مخاطبي.","22:10":"فسألت: ماذا أفعل يا رب؟ فأجابني الرب: قم وادخل دمشق، وهناك يقال لك ما يجب عليك أن تفعله.","22:11":"واقتادني مرافقي بيدي حتى أوصلوني إلى دمشق، لأني لم أكن أبصر بسبب شدة ذلك النور الباهر.","22:12":"وكان في دمشق رجل اسمه حنانيا، تقي كما تقضي الشريعة، يشهد له يهود دمشق جميعا شهادة حسنة.","22:13":"جاء إلي ووقف وقال: أيها الأخ شاول، أبصر. فعاد إلي بصري حالا، ورأيته أمامي،","22:14":"فقال: إله آبائنا اختارك مسبقا لتعرف إرادته، وترى البار وتسمع صوتا من فمه.","22:15":"فإنك ستكون شاهدا له، أمام جميع الناس، بما رأيت وسمعت.","22:16":"والآن لماذا تبطئ؟ قم تعمد واغتسل من خطاياك، داعيا باسم الرب».","22:17":"بعد ذلك رجعت إلى أورشليم. وبينما كنت أصلي في الهيكل غبت عن الوعي،","22:18":"فرأيت الرب يقول لي: عجل واترك أورشليم بسرعة، لأن أهلها يرفضون أن تشهد لي فيها.","22:19":"فقلت: يا رب، إنهم يعرفون أني كنت أبحث في المجامع عن المؤمنين بك، لأسجنهم وأجلدهم.","22:20":"وكنت حاضرا عندما قتل شهيدك استفانوس، وكنت راضيا بقتله، وحارسا لثياب قاتليه.","22:21":"ولكنه قال لي: اذهب، سأرسلك بعيدا إلى الأمم!»","22:22":"ظل المجتمعون يصغون حتى وصل بولس إلى ذكر الأمم، فصرخوا بقائد الكتيبة: «انزع هذا الرجل من الأرض! إنه لا يستحق الحياة!»","22:23":"ثم أخذوا يصيحون ويلوحون بثيابهم، ويذرون الغبار في الهواء.","22:24":"فأمر القائد جنوده أن يدخلوا بولس إلى المعسكر وأن يستجوبوه تحت جلد السياط ليعرف سبب الهتافات الصاخبة ضده.","22:25":"فلما ربطه الجنود ليجلدوه قال لقائد المئة الذي كان واقفا بقربه: «أيسمح لكم القانون بجلد مواطن روماني قبل محاكمته؟»","22:26":"فما إن سمع الضابط ذلك حتى ذهب إلى القائد وأخبره بالأمر، وقال: «أتعلم أية مخالفة كنا سنرتكب لو جلدنا هذا الرجل؟ إنه روماني الجنسية!»","22:27":"فذهب القائد بنفسه إلى بولس وسأله: «أأنت حقا روماني؟» فأجاب: «نعم!»","22:28":"فقال القائد: «أنا دفعت مبلغا كبيرا من المال لأحصل على الجنسية الرومانية». فقال بولس: «وأنا حاصل عليها بالولادة!»","22:29":"وفي الحال ابتعد عنه الجنود المكلفون باستجوابه تحت جلد السياط، ووقع الخوف في نفس القائد من عاقبة تقييده بالسلاسل، بعدما تحقق أنه روماني.","22:30":"وفي اليوم التالي أراد القائد أن ينظر في حقيقة التهمة التي وجهها اليهود إلى بولس، ففك قيوده، وأمر بإحضار رؤساء الكهنة وأعضاء المجلس اليهودي جميعا، واستدعى بولس وأوقفه أمامهم.","23:1":"فحدق بولس إلى المجلس، وقال: «أيها الإخوة، إني عشت لله بضمير صالح حتى هذا اليوم».","23:2":"فأمر حنانيا، رئيس الكهنة، واحدا من الواقفين لديه أن يضرب بولس على فمه،","23:3":"فقال له بولس: «ضربك الله، يا حائط المقبرة المبيض! كيف تجلس لتحاكمني وفقا للشريعة، ثم تخالف الشريعة فتأمر بضربي؟»","23:4":"فقال له الواقفون هناك: «أتشتم رئيس كهنة الله؟»","23:5":"فأجاب بولس: «لم أكن أعرف أيها الإخوة أنه رئيس كهنة فقد جاء في الكتاب: لا تشتم رئيس شعبك!»","23:6":"وإذ كان بولس يعلم أن بعض أعضاء المجلس من مذهب الصدوقيين، وبعضهم من مذهب الفريسيين، نادى في المجلس: «أيها الإخوة، أنا فريسي ابن فريسي، وإني أحاكم الآن لأنني أعتقد أن للموتى رجاء بالقيامة!»","23:7":"وهنا دب الخلاف بين الفريسيين والصدوقيين من أعضاء المجلس، فانقسم الحاضرون.","23:8":"فإن الصدوقيين ينكرون القيامة والملائكة والأرواح، أما الفريسيون فيقرون بها كلها.","23:9":"وعلا الصياح، فوقف بعض علماء الشريعة الموالين للفريسيين، يحتجون بحماسة، فقالوا: «لا نجد على هذا الرجل ذنبا، فلربما كلمه روح أو ملاك!»","23:10":"وتفاقم الخلاف حتى خاف القائد أن يشقوا بولس شقين، فأمر الجنود أن ينزلوا ويخطفوه من بينهم ويعيدوه إلى المعسكر.","23:11":"وفي الليلة التالية ظهر الرب لبولس وقال له: «تشجع، فكما أديت لي الشهادة في أورشليم، لابد أن تؤديها لي في روما أيضا».","23:12":"ولما طلع الصباح حاك بعض اليهود مؤامرة لقتل بولس، وحرموا على أنفسهم الطعام والشراب إلى أن يقتلوه.","23:13":"وكان عدد الذين حاكوا هذه المؤامرة نحو أربعين رجلا.","23:14":"وذهبوا إلى رؤساء الكهنة والشيوخ وقالوا: «حرام علينا الطعام والشراب حتى نقتل بولس.","23:15":"فاطلبوا من القائد بصفتكم أعضاء المجلس، أن يحضر بولس بحجة إعادة النظر في قضيته، ونحن مستعدون لاغتياله قبل وصوله إلى المجلس!»","23:16":"ولكن خبر هذه المؤامرة تسرب إلى ابن أخت بولس، فتوجه إلى المعسكر وأخبره بذلك.","23:17":"فاستدعى بولس أحد قواد المئات وطلب إليه أن يأخذ ابن أخته إلى القائد ليخبره بأمر هام.","23:18":"فأخذه إلى القائد وقال: «استدعاني السجين بولس وطلب أن أحضر هذا الشاب إليك، لأن عنده أمرا هاما يريد أن يخبرك به».","23:19":"فأمسك القائد الشاب بيده، وانفرد به، وسأله: «ما الأمر الذي تريد أن تخبرني به؟»","23:20":"فقال: «حاك اليهود مؤامرة على بولس، وسيطلبون منك أن تحضره إلى مجلسهم، بحجة إعادة النظر في قضيته،","23:21":"فلا تقبل طلبهم، لأن أكثر من أربعين رجلا منهم حرموا على أنفسهم الطعام والشراب ونصبوا كمينا لاغتياله، وهم الآن مستعدون لذلك، وينتظرون تلبية طلبهم!»","23:22":"فصرف القائد الشاب بعدما قال له: «لا تخبر أحدا بما أعلمتني به!»","23:23":"ودعا اثنين من قواد المئات لديه، وأمرهما قائلا: «جهزا مئتي جندي ليذهبوا إلى قيصرية الساعة التاسعة مساء الليلة ومعهم سبعون فارسا ومئتا حامل رمح،","23:24":"وبعض الدواب لتحمل بولس وتوصله سالما إلى الحاكم فيلكس».","23:25":"وكتب إلى الحاكم رسالة يقول فيها:","23:26":"«من كلوديوس ليسياس إلى سمو الحاكم فيلكس: سلام!","23:27":"هذا الرجل قبض عليه اليهود وحاولوا أن يقتلوه. وقد علمت أنه مواطن روماني فأسرعت إليه مع بعض الجنود وأنقذته.","23:28":"وأردت أن أعرف التهمة التي يتهمونه بها، فقدمته إلى مجلسهم،","23:29":"فتبين لي أن تهمته تختص بقضايا تتعلق بشريعتهم. ووجدت أنه لم يرتكب ذنبا يستحق عقوبة الموت أو السجن.","23:30":"ثم تبين لي أن جماعة من اليهود حاكوا مؤامرة لقتله، فأرسلته إليك بسرعة، وأمرت المدعين عليه أن يقدموا شكواهم لديك».","23:31":"وهكذا نقل الجنود بولس ليلا إلى أنتيباتريس، تنفيذا للأوامر الصادرة إليهم.","23:32":"وفي الصباح عادوا إلى المعسكر، وتركوا الفرسان يرافقون بولس إلى قيصرية.","23:33":"وهناك سلموه إلى الحاكم مع الرسالة.","23:34":"فقرأ الحاكم الرسالة، وسأل عن المقاطعة التي ينتمي بولس إليها. ولما علم أنه من كيليكية","23:35":"قال له: «سأنظر في قضيتك عندما يحضر المدعون عليك». وأمر بوضع بولس في قصر هيرودس، تحت الحراسة.","24:1":"وبعد خمسة أيام حضر إلى قيصرية وفد يضم حنانيا، رئيس الكهنة، وبعض الشيوخ، ومحاميا اسمه ترتلس، ليقدموا الدعوى للحاكم ضد بولس.","24:2":"فاستدعى الحاكم بولس، وبدأ ترتلس يوجه إليه الاتهام، فقال: «إن ما تم لنا بفضلك من سلام وافر وإصلاحات انتفع بها شعبنا بعنايتك","24:3":"يا سمو الحاكم فيلكس نرحب به، بجملته وفي كل مكان، بالشكر الجزيل.","24:4":"ولأني لا أريد أن أطيل الكلام عليك، أرجو أن تتلطف فتسمع عرضا موجزا لدعوانا:","24:5":"وجدنا هذا المتهم مخربا، يثير الفتنة بين جميع اليهود في البلاد كلها، وهو يتزعم مذهب النصارى.","24:6":"فلما حاول تدنيس هيكلنا أيضا، قبضنا عليه وأردنا أن نحاكمه بحسب شريعتنا.","24:7":"ولكن القائد ليسياس جاء وأخذه بالقوة من أيدينا،","24:8":"ثم أمر المدعين عليه بالترافع أمامك. وتستطيع الآن أن تتيقن من صحة دعوانا إذا قمت باستجوابه في هذا الأمر!»","24:9":"وأيد اليهود أعضاء الوفد ادعاء المحامي زاعمين أنه صحيح.","24:10":"وأشار الحاكم إلى بولس أن يقدم دفاعه، فقال: «أنا أعلم أنك تحكم في قضايا أمتنا منذ سنوات عديدة، ولذلك يسرني تقديم دفاعي عن نفسي بكل ارتياح.","24:11":"ويمكنك أن تتأكد أنه لم يمض على وصولي إلى أورشليم، للعبادة، أكثر من اثني عشر يوما.","24:12":"ولم يرني أحد من اليهود مرة واحدة في الهيكل أو المجامع أجادل أحدا أو أحرض الشعب على الفوضى.","24:13":"وهم لا يقدرون أن يثبتوا اتهامهم لي أمامك الآن.","24:14":"ولكني أعترف أمامك بأني أعبد إله آبائي بحسب المذهب الذي يصفونه بأنه بدعة، وأومن بكل ما كتب في الشريعة وكتب الأنبياء،","24:15":"ولي بالله ما لهم من رجاء ينتظرون تحقيقه: وهو أن القيامة ستحدث للأموات، الأبرار منهم والأشرار.","24:16":"لذلك أنا أيضا أدرب نفسي لكي أحيا دائما بضمير نقي أمام الله والناس.","24:17":"وبعد غياب عدة سنوات عن أورشليم، رجعت إليها أحمل بعض التبرعات إلى شعبي، وأقرب تقدمات.","24:18":"وبينما كنت أقوم بذلك، رآني في الهيكل بعض يهود مقاطعة أسيا، وكنت قد تطهرت. لم أكن وقتئذ وسط أي تجمع، ولا كنت أثير الفوضى.","24:19":"ولو كان عندهم دليل ضدي، لكانوا حضروا أمامك وشكوني حسب الأصول.","24:20":"والآن، ليذكر الحاضرون هنا الذنب الذي وجدوه علي عندما حاكموني أمام مجلسهم،","24:21":"غير ما أعلنته أمامهم حين قلت: أنتم تحاكمونني اليوم بسبب إيماني بقيامة الأموات».","24:22":"وكان فيلكس يعرف عن كثب أمور الطريق، فلما سمع دفاع بولس أرجأ إصدار الحكم، وقال للوفد المدعي: «سأحكم في دعواكم عندما يحضر القائد ليسياس».","24:23":"ثم أمر قائد المئة بوضع بولس تحت الحراسة، على أن تكون له بعض الحرية، وأن يسمح لأصدقائه بزيارته والقيام بخدمته.","24:24":"وبعد بضعة أيام جاء فيلكس ومعه زوجته دروسلا، وكانت يهودية، فاستدعى بولس واستمع إلى حديثه عن الإيمان بالمسيح يسوع.","24:25":"ولما تحدث بولس عن البر وضبط النفس والدينونة الآتية ارتعب فيلكس، وقال لبولس: «اذهب الآن، ومتى توفر لي الوقت أستدعيك ثانية».","24:26":"وكان فيلكس يأمل أن يدفع له بولس بعض المال ليطلقه، فأخذ يكثر من استدعائه والحديث معه.","24:27":"ومرت سنتان وبولس على هذه الحال. وأخيرا تعين بوركيوس فستوس حاكما خلفا لفيلكس. وإذ أراد فيلكس أن يكسب رضى اليهود ترك بولس في السجن.","25:1":"بعد ثلاثة أيام لتولي فستوس منصبه، ذهب من قيصرية إلى أورشليم.","25:2":"فجاءه رئيس الكهنة ووجهاء اليهود وعرضوا له دعواهم ضد بولس، وطلبوا منه","25:3":"بإلحاح أن يكرمهم بإحضار بولس إلى أورشليم. وكانوا قد نصبوا له كمينا على الطريق ليغتالوه.","25:4":"فأجابهم فستوس بأن بولس سيبقى محتجزا في قيصرية وأنه هو سيعود إليها بعد فترة قصيرة.","25:5":"وقال: «ليذهب معي أصحاب النفوذ منكم؛ فإن كان على هذا الرجل ذنب ما، فليتهموه به أمامي!»","25:6":"وقضى فستوس في أورشليم أياما لا تزيد على الثمانية أو العشرة، ثم عاد إلى قيصرية. وفي اليوم التالي لوصوله جلس على منصة القضاء، وأمر بإحضار بولس.","25:7":"فلما حضر اجتمع حوله اليهود الذين جاءوا من أورشليم، ووجهوا إليه تهما كثيرة وخطيرة عجزوا عن إثبات صحتها.","25:8":"فدافع بولس عن نفسه قائلا: «لم أرتكب ذنبا في حق شريعة اليهود، أو الهيكل، أو القيصر».","25:9":"ومع ذلك فقد أراد فستوس أن يكسب رضى اليهود، فسأل بولس: «هل تريد أن تذهب إلى أورشليم حيث تجري محاكمتك بحضوري على هذه التهم؟»","25:10":"فأجاب بولس: «أنا ماثل الآن في محكمة القيصر، وأمامها يجب أن تجري محاكمتي. لم أرتكب ذنبا في حق اليهود، وأنت تعلم هذا جيدا.","25:11":"ولو كنت ارتكبت جريمة أستحق عليها عقوبة الإعدام، لما كنت أهرب من الموت. ولكن مادامت تهم هؤلاء لي بلا أساس، فلا يحق لأحد أن يسلمني إليهم ليحاكموني. إني أستأنف دعواي إلى القيصر!»","25:12":"وتداول فستوس الأمر مع مستشاريه، ثم قال لبولس: «مادمت قد استأنفت دعواك إلى القيصر، فإلى القيصر تذهب!»","25:13":"وبعد بضعة أيام جاء الملك أغريباس وبرنيكي إلى قيصرية ليسلما على فستوس.","25:14":"ومكثا هناك أياما عديدة. فعرض فستوس على الملك قضية بولس قائلا: «هنا رجل تركه فيلكس سجينا.","25:15":"ولما ذهبت إلى أورشليم شكاه إلي رؤساء الكهنة والشيوخ، وطالبوا بإصدار الحكم عليه.","25:16":"فقلت لهم إنه ليس من عادة الرومان أن يصدروا حكما على أحد قبل أن يواجه الذين يتهمونه، لتتاح له فرصة الدفاع عن نفسه.","25:17":"فلما جاءوا إلى هنا أسرعت في اليوم التالي وعقدت جلسة للنظر في القضية، وأمرت بإحضار المتهم.","25:18":"فلما قابله متهموه لم يذكروا ذنبا واحدا مما كنت أتوقع أن يتهموه به،","25:19":"بل جادلوه في مسائل تختص بديانتهم وبرجل اسمه يسوع، مات وبولس يقول إنه حي!","25:20":"فحرت في الأمر، وعرضت على المتهم أن يذهب إلى أورشليم ويحاكم هناك،","25:21":"إلا أنه استأنف دعواه إلى جلالة القيصر ليحاكم في حضرته، فأمرت بحراسته حتى أرسله إلى القيصر».","25:22":"فقال أغريباس لفستوس: «أحب أن أسمع ما يقوله هذا الرجل». فأجاب: «غدا تسمعه».","25:23":"وفي اليوم التالي جاء أغريباس وبرنيكي، واستقبلا باحتفال باذخ، إذ دخلا قاعة الاستماع يحيط بهما القادة العسكريون ووجهاء المدينة. وأمر فستوس بإحضار بولس.","25:24":"فلما أحضر قال فستوس: «أيها الملك أغريباس، والسادة الحاضرون هنا جميعا: أمامكم هذا الرجل الذي شكاه إلي الشعب اليهودي كله في أورشليم وهم يصرخون أنه يجب ألا يبقى حيا","25:25":"وتبين لي أنه لم يفعل ما يستحق الإعدام. ولكنه استأنف دعواه إلى جلالة القيصر، فقررت أن أرسله إليه.","25:26":"ولكن ليس لي شيء أكيد أكتبه إلى جلالة القيصر بشأنه. لذلك أحضرته أمامكم جميعا، وخاصة أمامك أيها الملك أغريباس، حتى إذا تم النظر في قضيته أجد ما أكتبه.","25:27":"فمن غير المعقول، كما أرى، أن أرسل إلى القيصر سجينا دون تحديد التهم الموجهة إليه!»","26:1":"فقال أغريباس لبولس: «إننا نسمح لك بالدفاع عن نفسك». فأشار بولس بيده، وابتدأ دفاعه قائلا:","26:2":"«أيها الملك أغريباس، يسعدني أن أدافع عن نفسي في حضرتك، وأرد كل ما يتهمني به اليهود،","26:3":"وبخاصة لأنك تعرف تماما طقوسهم ومجادلاتهم. فألتمس أن تسمعني برحابة صدر.","26:4":"إن اليهود جميعا يعرفون نشأتي من البداية. فقد عشت بين شعبي في أورشليم منذ صغري.","26:5":"وماداموا يعرفونني من البداية، فلو أرادوا لشهدوا أنني كنت فريسيا، أي تابعا للمذهب الأكثر تشددا في ديانتنا.","26:6":"وأنا اليوم أحاكم لأن لي رجاء بأن يحقق الله ما وعد به آباءنا،","26:7":"ومازالت أسباط شعبنا الاثنا عشر تواظب على العبادة ليل نهار راجية تحقيقه. من أجل هذا الرجاء، أيها الملك، يتهمني اليهود.","26:8":"لماذا لا تصدقون أن الله يقيم الأموات؟","26:9":"وكنت أعتقد أنه يجب أن أبذل غاية جهدي لأقاوم اسم يسوع الناصري.","26:10":"وقد عملت على تنفيذ خطتي في أورشليم بتفويض خاص من رؤساء الكهنة، فألقيت في السجن عددا كبيرا من القديسين. وكنت أعطي صوتي بالموافقة عندما كان المجلس يحكم بإعدامهم.","26:11":"وكم عذبتهم في المجامع كلها لأجبرهم على التجديف. وقد بلغ حقدي عليهم درجة جعلتني أطاردهم في المدن التي في خارج البلاد.","26:12":"وتوجهت إلى مدينة دمشق بتفويض وترخيص من رؤساء الكهنة،","26:13":"فرأيت، أيها الملك، على الطريق عند الظهر نورا يفوق نور الشمس يسطع حولي وحول مرافقي،","26:14":"فسقطنا كلنا على الأرض. وسمعت صوتا يناديني باللغة العبرية قائلا: شاول، شاول، لماذا تضطهدني؟ يصعب عليك أن ترفس المناخس.","26:15":"فسألت: من أنت يا سيد؟ فأجاب: أنا يسوع الذي أنت تضطهده.","26:16":"انهض وقف على قدميك، فقد ظهرت لك لأعينك خادما لي وشاهدا بهذه الرؤيا التي تراني فيها الآن، وبالرؤى التي ستراني فيها بعد اليوم.","26:17":"وسأنقذك من شعبك ومن الأمم التي أرسلك إليها الآن،","26:18":"لتفتح عيونهم كي يرجعوا من الظلام إلى النور، ومن سيطرة الشيطان إلى الله، فينالوا غفران الخطايا ونصيبا بين الذين تقدسوا بالإيمان بي.","26:19":"ومن ذلك الحين لم أعاند الرؤيا السماوية، أيها الملك أغريباس.","26:20":"فبشرت أهل دمشق أولا، ثم أهل أورشليم ومنطقة اليهودية كلها، ثم الأجانب. فدعوت الجميع إلى التوبة والرجوع إلى الله، والقيام بأعمال تليق بالتوبة.","26:21":"وبسبب تبشيري قبض اليهود علي في الهيكل وحاولوا أن يقتلوني،","26:22":"ولكن الله حفظني حتى هذا اليوم، وبمعونته أقف أمام البسطاء والعظماء شاهدا له ولست أحيد عما تنبأ به موسى والأنبياء،","26:23":"من أن المسيح سيتألم فيكون أول من يقوم من بين الأموات، ويبشر بالنور شعبنا والشعوب الأخرى».","26:24":"وما إن وصل بولس في دفاعه إلى هذا الحد، حتى قاطعه فستوس قائلا بصوت عال: «جننت يا بولس! إن تبحرك في العلم أصابك بالجنون!»","26:25":"فقال بولس: «لست مجنونا يا سمو الحاكم فستوس، فأنا أنطق بكلام الحق والصواب.","26:26":"والملك الذي أخاطبه الآن صراحة يعرف هذه الأمور التي أتحدث عنها، وأنا متأكد أنه لا يخفى عليه شيء منها، لأنها لم تحدث في زاوية مظلمة!","26:27":"أيها الملك أغريباس، أتصدق أقوال الأنبياء؟ أنا أعلم أنك تصدقها!»","26:28":"فأجاب أغريباس: «قليلا بعد، وتقنعني بأن أصير مسيحيا!»","26:29":"فقال بولس: «سواء كان قليلا أم كثيرا، فإن صلاتي إلى الله لأجلك ولأجل الحاضرين هنا جميعا أن تصيروا مثلي، ولكن دون هذه السلاسل!»","26:30":"بعد ذلك قام الملك والحاكم وبرنيكي والحاضرون","26:31":"وتركوا القاعة، وهم يقولون بعضهم لبعض: «لم يرتكب هذا الرجل ما يستحق الموت أو السجن».","26:32":"وقال أغريباس لفستوس: «لو لم يستأنف هذا الرجل دعواه إلى القيصر لكان يمكن إطلاقه!»","27:1":"وأخيرا تقرر أن نسافر إلى إيطاليا بحرا، فتولى حراسة بولس وبعض السجناء الآخرين قائد مئة اسمه يوليوس، ينتمي إلى كتيبة أوغسطس.","27:2":"فركبنا سفينة قادمة من أدراميت، متجهة إلى موانئ مقاطعة أسيا. ورافقنا في الرحلة أرسترخس من مدينة تسالونيكي في مقاطعة مقدونية.","27:3":"وفي اليوم التالي وصلنا إلى صيدا. وعامل يوليوس بولس معاملة طيبة فسمح له بأن يزور أصدقاءه في صيدا ليتلقى منهم ما يحتاج إليه.","27:4":"وأقلعنا من ميناء صيدا، وسافرنا بمحاذاة شواطئ قبرص، لأن الريح كانت عكس اتجاه سيرنا.","27:5":"وعبرنا البحر المجاور لمقاطعتي كيليكية وبمفيلية، ووصلنا إلى ميناء ميرا في مقاطعة ليكية.","27:6":"وهناك وجد قائد المئة سفينة قادمة من الإسكندرية متجهة إلى إيطاليا، فأصعدنا إليها.","27:7":"وسافرت السفينة على مهل لعدة أيام، واقتربنا من شاطئ كنيدس بعد جهد، ولكن الريح منعتنا من دخول الميناء فلم نقدر أن ننزل هناك، فسافرنا على مقربة من شاطئ جزيرة كريت، مرورا بالقرب من رأس سلموني.","27:8":"وبعد جهد وصلنا إلى مكان يدعى الموانئ الجميلة بالقرب من مدينة لسائية.","27:9":"وقضينا هناك مدة طويلة، حتى مضى الصيف وأصبح السفر في البحر خطرا إذ كان الصوم أيضا قد مضى، فنصح بولس بحارة السفينة","27:10":"قائلا: «أيها الرجال، أرى في سفرنا الآن خطرا وخسارة عظيمة، لا على السفينة وحمولتها فقط، بل على حياتنا أيضا».","27:11":"على أن قائد المئة كان يميل إلى كلام ربان السفينة وصاحبها، لا إلى كلام بولس.","27:12":"ولما لم تكن الميناء صالحة لقضاء فصل الشتاء، فقد قرر معظم البحارة أن يغادروها، آملين الوصول إلى ميناء فينكس لقضاء الشتاء فيها، وقد كانت هذه الميناء في كريت تواجه الجنوب والشمال الغربيين.","27:13":"وهبت ريح خفيفة من الجنوب، فظن البحارة أنها ستدفعهم نحو فينكس، فرفعوا المرساة وأبحروا على مقربة من شاطئ كريت.","27:14":"ولكن ريحا عاصفة تعرف بالشمالية الشرقية هبت بعد قليل،","27:15":"فاندفعت السفينة ولم تقو على مقاومة الريح، فاستسلمنا. وحملتنا العاصفة","27:16":"إلى مكان قريب من جزيرة صغيرة اسمها كودا. وبعد جهد استطعنا أن نرفع قارب النجاة إلى ظهر السفينة.","27:17":"ثم أسرع البحارة باتخاذ الاحتياطات الضرورية، فشدوا وسط السفينة بالحبال. وخوفا من الانجراف إلى شواطئ الرمال المتحركة، أنزلوا الأشرعة والحبال، فأصبحت الريح تدفع السفينة.","27:18":"وفي اليوم الثاني اشتدت علينا العاصفة، فأخذوا يخففون من الحمولة.","27:19":"وفي اليوم الثالث رموا أثاث السفينة بأيديهم.","27:20":"وكانت العاصفة تشتد يوما بعد يوم، حتى إننا لم نر الشمس ولا النجوم عدة أيام، فانقطع كل أمل في النجاة.","27:21":"وكان المسافرون قد امتنعوا مدة طويلة عن تناول الطعام، فتقدم بولس إليهم وقال: «أيها الرجال، كان يجب أن تسمعوا كلامي ولا تقلعوا من كريت، فتسلموا من هذا الخطر والخسارة.","27:22":"ولكني الآن أدعوكم لتطمئنوا، فلن يفقد أحد منكم حياته. ولكن السفينة وحدها ستتحطم.","27:23":"فقد ظهر لي هذه الليلة ملاك من عند الله الذي أنا له وإياه أخدم،","27:24":"وقال لي: لا تخف يا بولس! فلابد أن تمثل أمام القيصر. وقد وهبك الله حياة جميع المسافرين معك!","27:25":"فاطمئنوا أيها الرجال، لأني أومن بالله وبأن ما قاله لي سيتم.","27:26":"ولكن لابد أن تجنح السفينة إلى إحدى الجزر».","27:27":"وفي منتصف الليلة الرابعة عشرة، والرياح تحملنا في بحر أدريا إلى حيث لا ندري، ظن البحارة أنهم يقتربون إلى البر.","27:28":"فقاسوا عمق المياه فوجدوه عشرين قامة. وبعد قليل قاسوا العمق فوجدوه خمس عشرة قامة.","27:29":"وخافوا أن تجنح السفينة إلى الصخور، فألقوا من مؤخرها أربع مراس، منتظرين طلوع الصباح.","27:30":"وحاول البحارة أن يهربوا من السفينة، فأنزلوا قارب النجاة بحجة أنهم سيلقون المراسي من مقدم السفينة.","27:31":"فقال بولس لقائد المئة والجنود: «إذا لم يبق هؤلاء البحارة في السفينة فلن تنجوا».","27:32":"فقطع الجنود حبال القارب وتركوه يسقط في الماء.","27:33":"ولما اقترب طلوع الصباح، طلب بولس إلى الجميع أن يأكلوا، وقال: «مرت أربعة عشر يوما وأنتم لا تأكلون شيئا،","27:34":"فأدعوكم إلى تناول الطعام، لأنه يساعدكم على النجاة. فلن يفقد أحد منكم شعرة من رأسه».","27:35":"ثم أخذ رغيفا، وشكر الله أمام الجميع، وكسره وابتدأ يأكل،","27:36":"فاطمأنوا كلهم وأكلوا.","27:37":"وكان عددنا في السفينة مئتين وستة وسبعين نفسا.","27:38":"وبعدما شبعوا رموا بالقمح في البحر ليخففوا حمولة السفينة.","27:39":"ولما طلع النهار، لم يستطع البحارة أن يميزوا المكان، ولكنهم أبصروا خليجا له شاطئ، فقرروا أن يدفعوا السفينة إليه، إذا استطاعوا،","27:40":"فقطعوا المراسي وتركوها تغرق، وحلوا الحبال التي تربط الدفة، ورفعوا الشراع الأمامي للريح، واتجهوا نحو الشاطئ.","27:41":"ولكن السفينة وصلت إلى مكان قليل المياه بين تيارين، فجنحوا بها إلى الشاطئ، فارتكز مقدمها وظل لا يتحرك، في حين أخذ مؤخرها يتفكك من عنف الأمواج.","27:42":"وارتأى الجنود أن يقتلوا السجناء حتى لا يسبح أحد منهم إلى الشاطئ ويهرب،","27:43":"ولكن قائد المئة كان يرغب في إنقاذ بولس، فمنع جنوده من تنفيذ رأيهم، وأمر القادرين على السباحة أن يسبحوا إلى الشاطئ قبل غيرهم،","27:44":"والباقين أن يحاولوا الوصول إليه على ألواح السفينة، أو على قطع من حطامها. وهكذا وصل الجميع إلى البر سالمين.","28:1":"وعرفنا بعدما نجونا أن الشاطئ الذي وصلناه هو جزيرة مالطة.","28:2":"واستقبلنا أهلها الغرباء بعطف كبير قل نظيره. فإذ كان المطر ينهمر والجو باردا، أوقدوا لنا نارا، ورحبوا بنا.","28:3":"وجمع بولس بعض الحطب وألقاه في النار، فخرجت أفعى، دفعتها الحرارة، وتعلقت بيده.","28:4":"ورأى أهل مالطة الأفعى عالقة بيده، فقال بعضهم لبعض: «لابد أن هذا الرجل قاتل، فإن العدل لم يدعه يحيا بعدما نجا من البحر».","28:5":"ولكن بولس نفض الأفعى في النار دون أن يمسه أذى.","28:6":"وانتظروا أن يتورم جسمه أو يقع ميتا فجأة. وطال انتظارهم، دون أن يصيبه ضرر، فغيروا رأيهم فيه وقالوا: «إنه إله!»","28:7":"وكانت بالقرب من المكان مزارع لحاكم الجزيرة بوبليوس، فدعانا وأحسن ضيافتنا ثلاثة أيام.","28:8":"وكان والد بوبليوس طريح الفراش مريضا بالحمى والإسهال الشديد. فزاره بولس وصلى، ووضع يديه عليه، فشفاه.","28:9":"فجاء عندئذ مرضى الجزيرة إليه ونالوا الشفاء،","28:10":"فأعطونا هدايا كثيرة، وزودونا عند رحيلنا بما نحتاج إليه في سفرنا.","28:11":"وبعد ثلاثة أشهر أقلعنا على سفينة من الإسكندرية، تحمل صورة الجوزاء (أي التوأمين)، كانت قد قضت فصل الشتاء في مالطة.","28:12":"فلما وصلنا إلى مدينة سراكوسا قضينا فيها ثلاثة أيام،","28:13":"ثم أبحرنا وسرنا على مقربة من الشاطئ حتى وصلنا مدينة ريغيون. وفي اليوم التالي هبت ريح جنوبية، فوصلنا إلى مدينة بوطيولي في يومين.","28:14":"ووجدنا هناك بعض الإخوة، فطلبوا إلينا أن نقضي معهم سبعة أيام. وهكذا وصلنا إلى روما.","28:15":"ولما سمع الإخوة فيها بوصولنا، خرجوا لاستقبالنا في ساحة أبيوس وفي الخانات الثلاثة. فلما رآهم بولس شكر الله وتشجع.","28:16":"ولما دخلنا روما سمح الضابط لبولس أن يقيم في منزل خاص مع الجندي الذي يحرسه.","28:17":"وبعد ثلاثة أيام دعا بولس وجهاء اليهود، وقال لهم: «أيها الإخوة، مع أني لم أفعل ما يسيء إلى الشعب، ولا إلى طقوس آبائنا، فقد سجنت في أورشليم وسلمت إلى الرومان،","28:18":"فاستجوبوني وأرادوا إطلاقي، لأنه لم يكن هناك ما يستوجب إعدامي.","28:19":"غير أن اليهود اعترضوا، فاضطررت إلى استئناف دعواي إلى القيصر. وهذا لا يعني أنني أشكو بني وطني بشيء.","28:20":"لذلك طلبت أن أراكم وأكلمكم؛ فأنا موثق بهذه السلسلة من أجل رجاء إسرائيل».","28:21":"فقالوا: «لم نتلق بشأنك أية رسالة من بلاد اليهودية، ولا جاء رسول من عند إخواننا يخبرنا عنك بشيء، أو يشتكي عليك.","28:22":"ولكننا نرى من المناسب أن نسمع رأيك، لأننا نعلم أن الناس في كل مكان يعارضون هذا المذهب!»","28:23":"فحددوا موعدا للقاء قادم، جاءوا فيه مع كثيرين إلى منزل بولس. فشهد لهم من الصباح إلى المساء شارحا لهم أمور ملكوت الله ومحاولا إقناعهم بالأمور المختصة بيسوع استنادا إلى شريعة موسى وكتب الأنبياء.","28:24":"فمنهم من اقتنع بكلامه، ومنهم من لم يؤمن.","28:25":"فاختلفوا فيما بينهم، وانصرفوا بعدما قال لهم: «صدق الروح القدس إذ قال لآبائكم بلسان النبي إشعياء:","28:26":"اذهب إلى هذا الشعب وقل له: سمعا ستسمعون، ولكنكم لا تفهمون! ونظرا ستنظرون، ولكنكم لا تبصرون!","28:27":"لأن قلب هذا الشعب قد صار غليظا، وآذانهم قد صارت ثقيلة السمع، وقد أغمضوا عيونهم. لئلا يبصروا بعيونهم، ويسمعوا بآذانهم، ويفهموا بقلوبهم، ويرجعوا إلي فأشفيهم!»","28:28":"وختم بولس كلامه بقوله: «اعلموا إذن أن الله قد أرسل خلاصه هذا إلى الأمم الأخرى، وهم سيستمعون إليه!»","28:29":"فلما قال هذا الكلام، خرج اليهود من عنده وهم يتجادلون بعنف.","28:30":"وأقام بولس سنتين كاملتين في المنزل الذي استأجره، وكان يرحب بجميع الذين يأتون لزيارته،","28:31":"مبشرا بملكوت الله، ومعلما الأمور المختصة بالرب يسوع المسيح بكل جرأة وبلا عائق."};
